BATCH={
  (28, 114): {
   "topic": "vvcTreatmentCombo",
   "lead": "\u062a\u0631\u0634\u062d\u0627\u062a \u0633\u0641\u06cc\u062f \u063a\u0644\u06cc\u0638 \u0686\u0633\u0628\u06cc\u062f\u0647 \u0628\u0647 \u062f\u06cc\u0648\u0627\u0631 \u0648\u0627\u0698\u0646 + \u062e\u0627\u0631\u0634 \u0648 \u0633\u0648\u0632\u0634 + \u0627\u062f\u0645/\u0627\u0631\u06cc\u062a\u0645 \u0648\u0644\u0648\u0627\u0631 \u0648\u0627\u0698\u0646: \u06a9\u0627\u0646\u062f\u06cc\u062f\u06cc\u0627\u0632 \u0648\u0644\u0648\u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u0648 \u067e\u0627\u0633\u062e \u062f\u0631\u0645\u0627\u0646\u06cc\u060c \u0622\u0632\u0648\u0644\u200c\u0647\u0627\u06cc \u0645\u0648\u0636\u0639\u06cc \u0633\u0647 \u062a\u0627 \u067e\u0646\u062c/\u0647\u0641\u062a \u0631\u0648\u0632.",
   "interpretation": "\u062f\u0631\u062f \u0633\u0648\u0632\u0634 \u0627\u062f\u0631\u0627\u0631 \u0648 \u062e\u0627\u0631\u0634 \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u062a\u0631\u0634\u062d\u200c\u0647\u0627\u06cc \u063a\u0644\u06cc\u0638 \u0633\u0641\u06cc\u062f \u00ab\u067e\u0646\u06cc\u0631\u06cc\u200c\u0645\u0627\u0646\u0646\u062f\u00bb \u0648 \u0639\u0644\u0627\u0645\u062a \u0627\u0644\u062a\u0647\u0627\u0628 \u0648\u0644\u0648\u0627\u0631 \u0648\u0627\u0698\u0646\u060c \u062a\u0635\u0648\u06cc\u0631 \u0645\u0639\u0645\u0648\u0644 \u06a9\u0627\u0646\u062f\u06cc\u062f\u06cc\u0627\u0632 \u0627\u0633\u062a\u061b \u062a\u0631\u06cc\u06a9\u0648\u0645\u0648\u0646\u0627 \u062a\u0631\u0634\u062d \u0686\u0631\u0645\u06cc-\u0632\u0631\u062f \u0648 \u00ab\u0633\u0631\u0648\u06cc\u06a9\u0633 \u062a\u0648\u062a\u200c\u0641\u0631\u0646\u06af\u06cc\u00bb \u0645\u06cc\u200c\u062f\u0647\u062f \u0648 BV \u062a\u0631\u0634\u062d \u0647\u0645\u06af\u0646 \u0631\u0642\u06cc\u0642 \u0628\u062f\u0648\u0646 \u0627\u0644\u062a\u0647\u0627\u0628 \u0628\u0631\u062c\u0633\u062a\u0647 \u0627\u0633\u062a \u0648 \u06af\u0648\u0646\u0648\u06a9\u0648\u06a9 \u062a\u0631\u0634\u062d \u0686\u0631\u0645\u06cc \u0633\u0631\u0648\u06cc\u06a9\u0627\u0644 \u0645\u06cc\u200c\u062f\u0647\u062f \u0648 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0637\u0628\u06cc\u0639\u06cc \u0646\u06cc\u0633\u062a\u061b \u062f\u0631\u0645\u0627\u0646 \u06a9\u0627\u0646\u062f\u06cc\u062f\u06cc\u0627\u0632 \u0628\u0627 \u0627\u06cc\u0645\u06cc\u062f\u0627\u0632\u0648\u0644\u200c\u0647\u0627\u06cc \u0645\u0648\u0636\u0639\u06cc \u0633\u0647 \u062a\u0627 \u0647\u0641\u062a \u0634\u0628\u0647 (\u06cc\u0627 \u062a\u0632\u0631\u06cc\u0642\u06cc \u062f\u0631 \u0635\u0648\u0631\u062a \u067e\u0634\u062a\u06cc\u0628\u0627\u0646\u06cc \u0634\u0631\u06cc\u06a9/\u0639\u0648\u062f) \u0628\u0647\u062a\u0631\u06cc\u0646 \u067e\u0627\u0633\u062e \u0627\u0633\u062a.",
   "reasons": ["\u062a\u0634\u062e\u06cc\u0635 \u06a9\u0627\u0646\u062f\u06cc\u062f\u06cc\u0627\u0632 \u0648 \u062f\u0631\u0645\u0627\u0646 \u0627\u06cc\u0645\u06cc\u062f\u0627\u0632\u0648\u0644 \u0645\u0648\u0636\u0639\u06cc \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062a\u0631\u06cc\u06a9\u0648\u0645\u0648\u0646\u0627 \u062a\u0631\u0634\u062d \u0632\u0631\u062f \u0628\u062f\u0628\u0648 \u0628\u0627 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u062a\u0648\u062a\u200c\u0641\u0631\u0646\u06af\u06cc \u0645\u06cc\u200c\u062f\u0647\u062f \u0646\u0647 \u067e\u0631\u0648\u0641\u0627\u06cc\u0644 \u0628\u0627\u0644\u06cc\u0646\u06cc \u0627\u06cc\u0646 \u0628\u06cc\u0645\u0627\u0631.", "BV \u062a\u0631\u0634\u062d \u0631\u0642\u06cc\u0642 \u0647\u0645\u06af\u0646 \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u06cc\u0645 \u0627\u0644\u062a\u0647\u0627\u0628 \u0628\u0631\u062c\u0633\u062a\u0647 \u062f\u0627\u0631\u062f.", "\u06af\u0648\u0646\u0648\u0631\u0647 \u0628\u06cc\u0634\u200c\u062a\u0631 \u0628\u0647\u200c\u0639\u0646\u0648\u0627\u0646 \u0639\u0627\u0645\u0644 \u0639\u0641\u0648\u0646\u062a \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0645\u0637\u0631\u062d \u0627\u0633\u062a \u0646\u0647 \u0627\u06cc\u0646 \u062a\u0635\u0648\u06cc\u0631."],
  },
  (28, 115): {
   "topic": "teratogenWindow",
   "lead": "\u0628\u06cc\u0634\u200c\u062a\u0631\u06cc\u0646 \u062d\u0633\u0627\u0633\u06cc\u062a \u062c\u0646\u06cc\u0646 \u0628\u0631\u0627\u06cc \u062a\u0634\u06a9\u06cc\u0644 \u0622\u0646\u0648\u0645\u0627\u0644\u06cc \u0627\u0635\u0644\u06cc \u0627\u0632 \u0627\u062b\u0631 \u0639\u0648\u0627\u0645\u0644 \u062a\u0631\u0627\u062a\u0648\u0698\u0646\u060c \u062f\u0631 \u0647\u0641\u062a\u0647\u200c\u0647\u0627\u06cc \u06f4 \u062a\u0627 \u06f1\u06f0 (\u067e\u0646\u062c\u0631\u0647\u0654 \u0627\u0631\u06af\u0627\u0646\u0648\u0698\u0646\u0632) \u0627\u0632 \u062d\u0627\u0645\u0644\u06af\u06cc \u0627\u0633\u062a.",
   "interpretation": "\u0647\u0641\u062a\u0647\u200c\u0647\u0627\u06cc \u06f3 \u062a\u0627 \u06f8-\u06f1\u06f0 \u0627\u0632 \u0644\u0642\u0627\u062d\u060c \u0632\u0645\u0627\u0646 \u0634\u06a9\u0644\u200c\u06af\u06cc\u0631\u06cc \u0627\u0631\u06af\u0627\u0646\u200c\u0647\u0627\u0633\u062a \u0648 \u0628\u06cc\u0634\u200c\u062a\u0631\u06cc\u0646 \u062a\u0623\u062b\u06cc\u0631 \u0633\u0627\u062e\u062a\u0627\u0631\u06cc \u062a\u0631\u0627\u062a\u0648\u0698\u0646\u200c\u0647\u0627 \u062f\u0631 \u0647\u0645\u06cc\u0646 \u0628\u0627\u0632\u0647 \u0645\u06cc\u200c\u0627\u0641\u062a\u062f\u061b \u062a\u0645\u0627\u0633 \u067e\u06cc\u0634 \u0627\u0632 \u0644\u0627\u0646\u0647\u200c\u06af\u0632\u06cc\u0646\u06cc \u0627\u062b\u0631 \u00ab\u0647\u0645\u0647\u200c\u06cc\u0627\u200c\u0647\u06cc\u0686\u00bb \u062f\u0627\u0631\u062f \u0648 \u062a\u0645\u0627\u0633\u200c\u0647\u0627\u06cc \u0628\u0639\u062f\u06cc \u0628\u06cc\u0634\u200c\u062a\u0631 \u0628\u0647 \u0631\u0634\u062f \u0648 \u0639\u0645\u0644\u06a9\u0631\u062f \u062f\u0633\u062a\u06af\u0627\u0647\u200c\u0647\u0627 \u0622\u0633\u06cc\u0628 \u0645\u06cc\u200c\u0632\u0646\u0646\u062f\u061b \u0631\u0627\u0647 \u062f\u0627\u0631\u0648 (\u062e\u0648\u0631\u0627\u06a9\u06cc/\u062a\u0632\u0631\u06cc\u0642\u06cc) \u062a\u0639\u06cc\u06cc\u0646\u200c\u06a9\u0646\u0646\u062f\u0647\u0654 \u0627\u0635\u0644\u06cc \u0645\u06cc\u0632\u0627\u0646 \u0627\u062b\u0631 \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0627\u0648\u0644 \u0628\u0647\u200c\u0637\u0648\u0631 \u06a9\u0644\u06cc \u062f\u0631\u0633\u062a \u0627\u0633\u062a \u0648\u0644\u06cc \u0686\u0627\u0631\u0686\u0648\u0628 \u062f\u0642\u06cc\u0642\u0650 \u0627\u0641\u0632\u0627\u06cc\u0634 \u062e\u0637\u0631\u060c \u0647\u0641\u062a\u0647\u200c\u0647\u0627\u06cc \u06f4 \u062a\u0627 \u06f1\u06f0 \u0627\u0633\u062a.", "\u06f4 \u062a\u0627 \u06f1\u06f0 \u0647\u0641\u062a\u06af\u06cc \u067e\u0646\u062c\u0631\u0647\u0654 \u0627\u0631\u06af\u0627\u0646\u0648\u0698\u0646\u0632 \u0648 \u062e\u0637\u0631 \u0633\u0627\u062e\u062a\u0627\u0631\u06cc \u0628\u06cc\u0634\u06cc\u0646\u0647 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u06f2 \u062a\u0627 \u06f3 \u0647\u0641\u062a\u0647 \u067e\u0633 \u0627\u0632 \u0644\u0642\u0627\u062d \u062f\u0648\u0631\u0647\u0654 \u00ab\u0647\u0645\u0647\u200c\u06cc\u0627\u200c\u0647\u06cc\u0686\u00bb \u0627\u0633\u062a \u0648 \u0646\u0627\u0647\u0646\u062c\u0627\u0631\u06cc\u200c\u0647\u0627\u06cc \u0645\u062a\u0639\u062f\u062f \u0631\u0627 \u0627\u06cc\u062c\u0627\u062f \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f.", "\u0645\u0633\u06cc\u0631 \u0645\u0635\u0631\u0641 \u062f\u0627\u0631\u0648 \u062a\u0639\u06cc\u06cc\u0646\u200c\u06a9\u0646\u0646\u062f\u0647\u0654 \u0627\u0635\u0644\u06cc \u062a\u0631\u0627\u062a\u0648\u0698\u0646\u06cc \u0628\u0648\u062f\u0646 \u0646\u06cc\u0633\u062a."],
  },
  (28, 116): {
   "topic": "hivPregTreatment",
   "lead": "\u062f\u0631 \u067e\u0631\u0633\u0634 \u00ab\u0635\u062d\u06cc\u062d \u0646\u06cc\u0633\u062a\u00bb \u0628\u0631\u0627\u06cc HIV \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0631 \u0627\u0633\u0627\u0633 \u067e\u0631\u0648\u062a\u06a9\u0644 \u0632\u0645\u0627\u0646 \u0637\u0631\u062d \u0633\u0624\u0627\u0644\u060c \u06af\u0632\u06cc\u0646\u0647\u0654 \u0634\u0631\u0648\u0639 \u062f\u0631\u0645\u0627\u0646 \u00ab\u0627\u0632 \u0647\u0645\u0627\u0646 \u0627\u0628\u062a\u062f\u0627\u06cc \u0628\u0627\u0631\u062f\u0627\u0631\u06cc\u00bb \u062f\u0631 \u0647\u0645\u0647\u0654 \u0628\u06cc\u0645\u0627\u0631\u0627\u0646 \u0628\u0647\u200c\u0639\u0646\u0648\u0627\u0646 \u06af\u0632\u0627\u0631\u0647\u0654 \u063a\u0644\u0637 \u06a9\u0644\u06cc\u062f \u062e\u0648\u0631\u062f\u0647 \u0627\u0633\u062a.",
   "interpretation": "\u0627\u0647\u062f\u0627\u0641 \u0645\u062f\u06cc\u0631\u06cc\u062a HIV \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u06a9\u0627\u0647\u0634 \u0627\u0646\u062a\u0642\u0627\u0644 \u0639\u0645\u0648\u062f\u06cc \u0628\u0627 \u062a\u0631\u06a9\u06cc\u0628\u200c\u0647\u0627\u06cc \u0636\u062f\u0648\u06cc\u0631\u0648\u0633\u06cc \u0648 \u0627\u0646\u062a\u062e\u0627\u0628 \u0631\u0648\u0634 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0628\u0631 \u0627\u0633\u0627\u0633 \u0648\u0636\u0639\u06cc\u062a \u0648\u06cc\u0631\u0648\u0633 \u0648 \u063a\u0648\u0644 \u0627\u0633\u062a\u061b \u062f\u0631 \u067e\u0631\u0648\u062a\u06a9\u0644\u200c\u0647\u0627\u06cc \u0632\u0645\u0627\u0646 \u0637\u0631\u062d \u0633\u0624\u0627\u0644\u060c \u062a\u0635\u0645\u06cc\u0645 \u0634\u0631\u0648\u0639 \u062f\u0631\u0645\u0627\u0646 \u0628\u0631 \u067e\u0627\u06cc\u0647\u0654 \u0634\u0645\u0627\u0631\u0634 CD4 \u0648 \u0628\u0627\u0631 \u0648\u06cc\u0631\u0648\u0633\u06cc \u06af\u0631\u0641\u062a\u0647 \u0645\u06cc\u200c\u0634\u062f \u0648 \u0639\u0628\u0627\u0631\u062a \u00ab\u0627\u0632 \u0647\u0645\u0627\u0646 \u0627\u0628\u062a\u062f\u0627 \u0628\u0631\u0627\u06cc \u0647\u0645\u0647\u0654 \u0628\u06cc\u0645\u0627\u0631\u0627\u0646\u00bb \u06af\u0632\u0627\u0631\u0647\u0654 \u0627\u0646\u062a\u062e\u0627\u0628\u200c\u0634\u062f\u0647\u0654 \u0633\u0624\u0627\u0644 (\u0628\u0647 \u0645\u0639\u0646\u0627\u06cc \u06af\u0632\u0627\u0631\u0647\u0654 \u063a\u0644\u0637) \u0628\u0648\u062f\u0647 \u0627\u0633\u062a\u061b \u06a9\u0627\u0647\u0634 \u0627\u0646\u062a\u0642\u0627\u0644 \u0628\u0627 \u0636\u062f\u0648\u06cc\u0631\u0648\u0633\u200c\u062f\u0631\u0645\u0627\u0646\u06cc \u0648 \u0646\u0642\u0634 \u0632\u06cc\u062f\u0648\u0648\u062f\u06cc\u0646 \u062f\u0631 \u0647\u0645\u0627\u0646 \u0645\u062a\u0646 \u0627\u0645\u0636\u0627 \u0634\u062f\u0647\u200c\u0627\u0633\u062a.",
   "reasons": ["\u06a9\u0627\u0647\u0634 \u0627\u0646\u062a\u0642\u0627\u0644 \u0628\u0647 \u062c\u0646\u06cc\u0646 \u0628\u0627 \u0636\u062f\u0648\u06cc\u0631\u0648\u0633 \u06af\u0632\u0627\u0631\u0647\u0654 \u062f\u0631\u0633\u062a \u0627\u06cc\u0646 \u0645\u062a\u0646 \u0627\u0633\u062a.", "\u0634\u0631\u0648\u0639 \u062f\u0631\u0645\u0627\u0646 \u0627\u0632 \u0647\u0645\u0627\u0646 \u0627\u0628\u062a\u062f\u0627 \u062f\u0631 \u0647\u0645\u0647\u0654 \u0628\u06cc\u0645\u0627\u0631\u0627\u0646\u060c \u0637\u0628\u0642 \u06a9\u0644\u06cc\u062f \u0627\u06cc\u0646 \u067e\u0631\u0633\u0634 \u06af\u0632\u0627\u0631\u0647\u0654 \u063a\u0644\u0637 \u0634\u0645\u0631\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d (\u06af\u0632\u06cc\u0646\u0647\u0654 \u0645\u0648\u0631\u062f\u0646\u0638\u0631 \u00ab\u0635\u062d\u06cc\u062d \u0646\u06cc\u0633\u062a\u00bb).", "\u062a\u0631\u062c\u06cc\u062d \u0633\u0632\u0627\u0631\u06cc\u0646 \u062f\u0631 \u067e\u0631\u062f\u0647\u0654 \u0633\u0627\u0644\u0645 \u062f\u0631 \u0645\u062a\u0646 \u067e\u0631\u0648\u062a\u06a9\u0644\u06cc \u0627\u06cc\u0646 \u0633\u0624\u0627\u0644 \u062c\u0627\u06cc\u06af\u0627\u0647 \u062f\u0627\u0634\u062a\u0647 \u0627\u0633\u062a.", "\u0632\u06cc\u062f\u0648\u0648\u062f\u06cc\u0646 \u062f\u0631 \u0645\u062a\u0646\u200c\u0647\u0627\u06cc \u0645\u0639\u062a\u0628\u0631 \u0627\u0632 \u06a9\u0645\u200c\u0639\u0627\u0631\u0636\u0647\u200c\u062a\u0631\u06cc\u0646 \u06af\u0632\u06cc\u0646\u0647\u200c\u0647\u0627\u06cc \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0634\u0645\u0631\u062f\u0647 \u0645\u06cc\u200c\u0634\u062f \u0648 \u062f\u0631\u0633\u062a \u0627\u0633\u062a."],
  },
  (28, 117): {
   "topic": "earlyRadiationExposure",
   "lead": "\u062a\u0645\u0627\u0633 \u067e\u06cc\u0634 \u0627\u0632 \u0644\u0627\u0646\u0647\u200c\u06af\u0632\u06cc\u0646\u06cc (\u062f\u0648 \u0647\u0641\u062a\u0647\u0654 \u0646\u062e\u0633\u062a) \u0628\u0627 \u0627\u0635\u0644 \u00ab\u0647\u0645\u0647\u200c\u06cc\u0627\u200c\u0647\u06cc\u0686\u00bb \u062a\u0641\u0633\u06cc\u0631 \u0645\u06cc\u200c\u0634\u0648\u062f \u06cc\u0627 \u0645\u0631\u06af \u062c\u0646\u06cc\u0646 \u06cc\u0627 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0637\u0628\u06cc\u0639\u06cc \u0628\u062f\u0648\u0646 \u0622\u0646\u0648\u0645\u0627\u0644\u06cc.",
   "interpretation": "\u062f\u0631 \u067e\u0631\u062a\u0648\u06af\u06cc\u0631\u06cc\u200c\u0647\u0627\u06cc \u0627\u0646\u062c\u0627\u0645\u200c\u0634\u062f\u0647 \u067e\u06cc\u0634 \u0627\u0632 \u0644\u0627\u0646\u0647\u200c\u06af\u0632\u06cc\u0646\u06cc (\u062a\u0642\u0631\u06cc\u0628\u0627\u064b \u06f1\u06f4 \u0631\u0648\u0632 \u0627\u0648\u0644 \u067e\u0633 \u0627\u0632 \u0644\u0642\u0627\u062d)\u060c \u0633\u0644\u0648\u0644\u200c\u0647\u0627\u06cc \u0647\u0645\u0647\u200c\u062a\u0648\u0627\u0646 \u062f\u0631 \u0628\u0631\u0627\u0628\u0631 \u0622\u0633\u06cc\u0628 \u06cc\u0627 \u0645\u06cc\u200c\u0645\u06cc\u0631\u0646\u062f \u06cc\u0627 \u0628\u0647\u200c\u0637\u0648\u0631 \u06a9\u0627\u0645\u0644 \u062a\u0631\u0645\u06cc\u0645 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f \u0648 \u0627\u062b\u0631 \u062a\u0631\u0627\u062a\u0648\u0698\u0646\u06cc\u06a9 \u0645\u0648\u0631\u062f \u0627\u0646\u062a\u0638\u0627\u0631 \u0646\u06cc\u0633\u062a\u061b \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u062f\u0631 \u0635\u0648\u0631\u062a \u0622\u0633\u06cc\u0628 \u063a\u06cc\u0631\u0642\u0627\u0628\u0644\u200c\u062a\u0631\u0645\u06cc\u0645 \u067e\u06cc\u0627\u0645\u062f \u0645\u062d\u062a\u0645\u0644\u060c \u0645\u0631\u06af \u062c\u0646\u06cc\u0646/\u0633\u0642\u0637 \u0627\u0648\u0644\u06cc\u0647 \u0627\u0633\u062a \u0648 \u0646\u0627\u0647\u0646\u062c\u0627\u0631\u06cc\u200c\u0647\u0627\u06cc \u0645\u0627\u062f\u0631\u0632\u0627\u062f\u06cc \u0686\u0646\u062f\u06af\u0627\u0646\u0647 \u0628\u0647 \u0641\u0627\u0632 \u0627\u0631\u06af\u0627\u0646\u0648\u0698\u0646\u0632 (\u0647\u0641\u062a\u0647\u200c\u0647\u0627\u06cc \u06f3 \u062a\u0627 \u06f8) \u0645\u0631\u0628\u0648\u0637 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f \u0648 \u0644\u0648\u0633\u0645\u06cc\u200c\u0647\u0627\u06cc \u06a9\u0648\u062f\u06a9\u06cc \u0627\u062b\u0631 \u062f\u0648\u0631 \u0648 \u0646\u0627\u062f\u0631\u062a\u0631 \u0627\u0633\u062a.",
   "reasons": ["\u0644\u0648\u0633\u0645\u06cc\u200c\u0647\u0627\u06cc \u062f\u0648\u0631\u0627\u0646 \u06a9\u0648\u062f\u06a9\u06cc \u0627\u062b\u0631 \u062f\u0648\u0631 \u0648 \u06a9\u0645\u200c\u0627\u062d\u062a\u0645\u0627\u0644\u200c\u062a\u0631 \u0627\u06cc\u0646 \u0645\u0648\u0642\u0639\u06cc\u062a\u200c\u0627\u0646\u062f.", "\u0627\u0635\u0644 \u00ab\u0647\u0645\u0647\u200c\u06cc\u0627\u200c\u0647\u06cc\u0686\u00bb \u0646\u0627\u0647\u0646\u062c\u0627\u0631\u06cc \u062a\u0631\u0627\u062a\u0648\u0698\u0646\u06cc\u06a9 \u0631\u0627 \u0645\u0646\u062a\u0641\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648\u0644\u06cc \u062f\u0631 \u06af\u0632\u06cc\u0646\u0647\u200c\u0628\u0646\u062f\u06cc \u0627\u06cc\u0646 \u0633\u0624\u0627\u0644 \u067e\u0627\u0633\u062e \u0645\u0631\u062c\u0639\u060c \u0645\u0631\u06af \u062c\u0646\u06cc\u0646 \u062f\u0631 \u0635\u0648\u0631\u062a \u0622\u0633\u06cc\u0628 \u0634\u062f\u06cc\u062f \u0627\u0633\u062a.", "\u062f\u0631 \u0627\u062b\u0631 \u00ab\u0647\u0645\u0647\u200c\u06cc\u0627\u200c\u0647\u06cc\u0686\u00bb \u067e\u06cc\u0627\u0645\u062f \u0645\u062d\u062a\u0645\u0644 \u062f\u0631 \u0635\u0648\u0631\u062a \u0622\u0633\u06cc\u0628 \u063a\u06cc\u0631\u0642\u0627\u0628\u0644\u200c\u062a\u0631\u0645\u06cc\u0645 \u0645\u0631\u06af \u062c\u0646\u06cc\u0646 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0646\u0627\u0647\u0646\u062c\u0627\u0631\u06cc\u200c\u0647\u0627\u06cc \u0645\u062a\u0639\u062f\u062f \u0645\u0627\u062f\u0631\u0632\u0627\u062f\u06cc \u0645\u062e\u0635\u0648\u0635 \u0641\u0627\u0632 \u0627\u0631\u06af\u0627\u0646\u0648\u0698\u0646\u0632 \u0627\u0633\u062a \u0646\u0647 \u067e\u06cc\u0634 \u0627\u0632 \u0644\u0627\u0646\u0647\u200c\u06af\u0632\u06cc\u0646\u06cc."],
  },
  (28, 119): {
   "topic": "earlyPregSerialHcg",
   "lead": "HCG=\u06f9\u06f8\u06f0 \u0628\u0627 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u062a\u0631\u0627\u0646\u0633\u200c\u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u0628\u062f\u0648\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc \u0648 \u0628\u062f\u0648\u0646 \u062a\u0648\u062f\u0647\u0654 \u0622\u062f\u0646\u06a9\u0633: \u062a\u06cc\u062a\u0631 \u0632\u06cc\u0631 \u0646\u0627\u062d\u06cc\u0647\u0654 \u062a\u0641\u06a9\u06cc\u06a9 \u0627\u0633\u062a \u0648 \u0642\u062f\u0645 \u062f\u0631\u0633\u062a\u060c \u0633\u0644\u0627\u06cc\u0631 BHCG \u062f\u0631 \u06f4\u06f8 \u0633\u0627\u0639\u062a \u0628\u0639\u062f.",
   "interpretation": "\u0628\u0627 \u062a\u06cc\u062a\u0631 \u06f9\u06f8\u06f0 \u06a9\u0647 \u0632\u06cc\u0631 \u0622\u0633\u062a\u0627\u0646\u0647\u0654 \u0646\u0627\u062d\u06cc\u0647\u0654 \u062a\u0641\u06a9\u06cc\u06a9 \u0645\u0639\u0645\u0648\u0644 (\u06f1\u06f5\u06f0\u06f0-\u06f2\u06f0\u06f0\u06f0 \u0628\u0631\u0627\u06cc \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u062a\u0631\u0627\u0646\u0633\u200c\u0648\u0627\u0698\u06cc\u0646\u0627\u0644) \u0627\u0633\u062a\u060c \u0646\u0628\u0648\u062f \u0633\u0627\u06a9 \u062d\u0627\u0645\u0644\u06af\u06cc \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc \u0647\u0646\u0648\u0632 \u062f\u0627\u0644 \u0628\u0631 \u0642\u0637\u0639\u06cc\u062a \u0646\u06cc\u0633\u062a \u0648 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0627 \u0645\u062d\u0644 \u0646\u0627\u0645\u0639\u0644\u0648\u0645 \u0628\u0627 BHCG \u0633\u0631\u06cc\u0627\u0644 \u067e\u06cc\u06af\u06cc\u0631\u06cc \u0645\u06cc\u200c\u0634\u0648\u062f: \u0635\u0639\u0648\u062f \u0628\u06cc\u0634 \u0627\u0632 ~\u06f5\u06f0\u066a \u062f\u0631 \u06f4\u06f8 \u0633\u0627\u0639\u062a \u0628\u0647\u200c\u0646\u0641\u0639 \u062d\u0627\u0645\u0644\u06af\u06cc \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc \u0633\u0627\u0644\u0645\u060c \u0627\u0644\u06af\u0648\u06cc \u06a9\u0627\u0647\u0634 \u06cc\u0627 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u062f\u0631 \u0633\u0642\u0637 \u0648 \u0627\u0644\u06af\u0648\u06cc \u0645\u062a\u0632\u0644\u0632\u0644/\u0646\u0627\u06a9\u0627\u0641\u06cc \u062f\u0631 EP \u0627\u0633\u062a\u061b \u062a\u06a9\u0631\u0627\u0631 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u062f\u0631 \u0647\u0645\u0627\u0646 \u062a\u06cc\u062a\u0631 \u0628\u062f\u0648\u0646 \u0645\u0631\u062c\u0639 \u0631\u0648\u0646\u062f BHCG \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u06a9\u0645\u06a9\u200c\u06a9\u0646\u0646\u062f\u0647 \u0646\u06cc\u0633\u062a \u0648 \u0645\u062a\u0648\u062a\u0631\u06a9\u0633\u0627\u062a \u0628\u062f\u0648\u0646 \u0627\u062b\u0628\u0627\u062a EP \u0648 \u0631\u062f \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc \u0642\u0627\u0628\u0644\u200c\u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0646\u06cc\u0633\u062a \u0648 \u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0627\u0648\u0631\u0698\u0627\u0646\u0633 \u0641\u0642\u0637 \u062f\u0631 \u0639\u0644\u0627\u06cc\u0645 \u0646\u0627\u067e\u0627\u06cc\u062f\u0627\u0631 \u0627\u0633\u062a.",
   "reasons": ["\u062a\u06a9\u0631\u0627\u0631 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u062f\u0631 \u0647\u0645\u06cc\u0646 \u062a\u06cc\u062a\u0631 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0647\u0646\u0648\u0632 \u063a\u06cc\u0631\u0642\u0637\u0639\u06cc \u0627\u0633\u062a.", "\u0633\u0644\u0627\u06cc\u0631 BHCG \u062f\u0631 \u06f4\u06f8 \u0633\u0627\u0639\u062a \u0628\u0639\u062f \u0642\u062f\u0645 \u0645\u0646\u0637\u0642\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0645\u062a\u0648\u062a\u0631\u06a9\u0633\u0627\u062a \u0628\u062f\u0648\u0646 \u062a\u0623\u06cc\u06cc\u062f \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062e\u0627\u0631\u062c\u200c\u0631\u062d\u0645\u06cc \u0648 \u0631\u062f \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0637\u0628\u06cc\u0639\u06cc \u0646\u0628\u0627\u06cc\u062f \u0645\u0635\u0631\u0641 \u0634\u0648\u062f.", "\u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0627\u0648\u0631\u0698\u0627\u0646\u0633 \u062f\u0631 \u0628\u06cc\u0645\u0627\u0631 \u067e\u0627\u06cc\u062f\u0627\u0631 \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a."],
  },
  (28, 120): {
   "topic": "agusWorkup",
   "lead": "\u067e\u0627\u067e\u200c\u0627\u0633\u0645\u06cc\u0631 AGUS \u062f\u0631 \u0632\u0646 \u06f4\u06f7 \u0633\u0627\u0644\u0647: \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u062e\u0637\u0631 \u0622\u062f\u0646\u0648\u06a9\u0627\u0631\u0633\u06cc\u0646\u0648\u0645 \u0622\u0646\u062f\u0648\u0645\u062a\u0631/\u0622\u0646\u062f\u0648\u0633\u0631\u0648\u06cc\u06a9\u0633\u060c \u062c\u0632\u0648 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0627\u0644\u0632\u0627\u0645\u06cc\u060c \u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0627\u0633\u062a.",
   "interpretation": "\u06af\u0632\u0627\u0631\u0634 \u0633\u0644\u0648\u0644\u200c\u0647\u0627\u06cc \u063a\u062f\u0647\u200c\u0627\u06cc \u0622\u062a\u06cc\u067e\u06cc\u06a9\u0627\u0644 \u0628\u0627 \u0645\u0639\u0646\u0627\u062f\u0627\u0631\u06cc \u0646\u0627\u0645\u0634\u062e\u0635 (AGUS) \u062e\u0637\u0631 \u0622\u062f\u0646\u0648\u06a9\u0627\u0631\u0633\u06cc\u0646\u0648\u0645 \u062f\u0631 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0648 \u0622\u0646\u062f\u0648\u0633\u0631\u0648\u06cc\u06a9\u0633 \u0631\u0627 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f \u0648 \u0627\u0644\u06af\u0648\u06cc \u06a9\u0627\u0631\u0622\u067e \u0645\u0639\u0645\u0648\u0644 \u0634\u0627\u0645\u0644 \u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc+ECC \u0648 \u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 (\u062f\u0631 \u0632\u0646\u0627\u0646 \u2265\u06f3\u06f5 \u0633\u0627\u0644 \u06cc\u0627 \u0628\u0627 \u0633\u0627\u0628\u0642\u0647\u0654 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u063a\u06cc\u0631\u0637\u0628\u06cc\u0639\u06cc) \u0627\u0633\u062a\u061b \u062a\u06a9\u0631\u0627\u0631 \u0633\u0627\u062f\u0647\u0654 \u067e\u0627\u067e\u200c\u0627\u0633\u0645\u06cc\u0631 \u06cc\u0627 \u062f\u0631\u0645\u0627\u0646 \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0645\u0648\u0636\u0639\u06cc \u0628\u062f\u0648\u0646 \u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u0646\u0627\u06a9\u0627\u0641\u06cc \u0627\u0633\u062a \u0648 \u062a\u0635\u0645\u06cc\u0645 \u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc/\u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u062c\u0627\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0631\u0627 \u0646\u0645\u06cc\u200c\u06af\u06cc\u0631\u062f.",
   "reasons": ["\u062a\u06a9\u0631\u0627\u0631 \u067e\u0627\u067e\u200c\u0627\u0633\u0645\u06cc\u0631 \u062f\u0631 AGUS \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a.", "\u06a9\u0648\u0631\u062a\u0627\u0698 \u062a\u0634\u062e\u06cc\u0635\u06cc \u062a\u0647\u0627\u062c\u0645\u06cc\u200c\u062a\u0631 \u0627\u0633\u062a \u0648 \u0628\u06cc\u0648\u067e\u0633\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u067e\u0644\u0647\u0654 \u0627\u0648\u0644 \u0627\u06cc\u0646 \u06a9\u0627\u0631\u0622\u067e \u0627\u0633\u062a.", "\u0628\u06cc\u0648\u067e\u0633\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0628\u0631\u0627\u06cc \u0633\u0644\u0648\u0644\u200c\u0647\u0627\u06cc \u063a\u062f\u0647\u200c\u0627\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646 \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u062f\u0631 \u0635\u0648\u0631\u062a \u0646\u06cc\u0627\u0632 \u0645\u0631\u062d\u0644\u0647\u0654 \u0628\u0639\u062f \u0627\u0633\u062a."],
  },
  (28, 121): {
   "topic": "firstPrenatalVisitContent",
   "lead": "\u062a\u0631\u06a9\u06cc\u0628 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0648\u06cc\u0632\u06cc\u062a \u0627\u0648\u0644 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc (\u06f1\u06f2 \u0647\u0641\u062a\u0647): \u062a\u062c\u0648\u06cc\u0632 \u0627\u0633\u06cc\u062f \u0641\u0648\u0644\u06cc\u06a9 + \u0622\u0632\u0645\u0627\u06cc\u0634\u0627\u062a \u0631\u0648\u062a\u06cc\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc + \u062f\u0631\u062e\u0648\u0627\u0633\u062a \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0627\u0648\u0644.",
   "interpretation": "\u062f\u0631 \u067e\u0646\u062c\u0631\u0647\u0654 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0627\u0648\u0644\u060c \u0648\u06cc\u0632\u06cc\u062a \u0627\u0648\u0644 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0634\u0627\u0645\u0644 \u062b\u0628\u062a \u0634\u0631\u0627\u06cc\u0637 \u0648 \u0622\u0632\u0645\u0627\u06cc\u0634\u200c\u0647\u0627\u06cc \u0631\u0648\u062a\u06cc\u0646\u060c \u062a\u062c\u0648\u06cc\u0632 \u0627\u0633\u06cc\u062f \u0641\u0648\u0644\u06cc\u06a9 (\u062f\u0633\u062a\u200c\u06a9\u0645 \u062a\u0627 \u067e\u0627\u06cc\u0627\u0646 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0627\u0648\u0644) \u0648 \u062f\u0631\u062e\u0648\u0627\u0633\u062a \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u062a\u0631\u06a9\u06cc\u0628\u06cc \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0627\u0648\u0644 (NT \u0648 \u0633\u0631\u0648\u0644\u0648\u0698\u06cc) \u0627\u0633\u062a\u061b \u0627\u0642\u062f\u0627\u0645\u0627\u062a \u0645\u062b\u0644 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0628\u0631\u0627\u06cc \u062a\u0639\u06cc\u06cc\u0646 \u0633\u0646 \u062f\u0642\u06cc\u0642 \u0632\u0645\u0627\u0646\u06cc \u0644\u0627\u0632\u0645 \u0627\u0633\u062a \u06a9\u0647 \u062a\u0627\u0631\u06cc\u062e \u0642\u0627\u0639\u062f\u06af\u06cc \u0646\u0627\u0645\u0634\u062e\u0635 \u0628\u0627\u0634\u062f \u0648 \u0633\u0627\u06cc\u0631 \u062a\u0631\u06a9\u06cc\u0628\u200c\u0647\u0627 \u06cc\u0627 \u0646\u0627\u0642\u0635\u200c\u0627\u0646\u062f \u06cc\u0627 \u0627\u0642\u062f\u0627\u0645\u0627\u062a\u06cc \u0628\u0631\u0627\u06cc \u062f\u0648\u0631\u0647\u200c\u0647\u0627\u06cc \u062f\u06cc\u06af\u0631 \u062f\u0627\u0631\u0646\u062f.",
   "reasons": ["\u0627\u06cc\u0646 \u06af\u0632\u06cc\u0646\u0647 \u0628\u0627 \u0627\u0644\u062d\u0627\u0642 \u0628\u062e\u0634 \u0645\u0631\u0628\u0648\u0637 \u0628\u0647 \u062f\u06cc\u0627\u0628\u062a \u0646\u0627\u0647\u0645\u0627\u0647\u0646\u06af \u0627\u0633\u062a \u0648 \u062a\u0631\u06a9\u06cc\u0628 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u06a9\u0627\u0645\u0644 \u0646\u06cc\u0633\u062a.", "\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u062a\u0639\u06cc\u06cc\u0646 \u0633\u0646 \u062f\u0642\u06cc\u0642 \u0628\u062f\u0648\u0646 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u062a\u0631\u06a9\u06cc\u0628\u06cc\u060c \u0633\u0627\u062e\u062a\u0627\u0631 \u06a9\u0627\u0645\u0644 \u067e\u0646\u062c\u0631\u0647\u0654 \u0627\u0648\u0644 \u0646\u06cc\u0633\u062a.", "\u0627\u0633\u06cc\u062f \u0641\u0648\u0644\u06cc\u06a9 + \u0622\u0632\u0645\u0627\u06cc\u0634\u0627\u062a \u0631\u0648\u062a\u06cc\u0646 + \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0627\u0648\u0644 \u062a\u0631\u06a9\u06cc\u0628 \u06a9\u0627\u0645\u0644 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0648\u0627\u06a9\u0633\u06cc\u0646\u0627\u0633\u06cc\u0648\u0646 \u0628\u0647 \u0627\u06cc\u0646 \u0634\u06a9\u0644 \u0628\u062e\u0634\u06cc \u0627\u0632 \u062f\u0633\u062a\u0648\u0631 \u0648\u06cc\u0632\u06cc\u062a \u0627\u0648\u0644 \u0646\u06cc\u0633\u062a."],
  },
  (28, 122): {
   "topic": "primaryAmenorrheaWorkup",
   "lead": "\u0622\u0645\u0646\u0648\u0631\u0647\u0654 \u0627\u0648\u0644\u06cc\u0647 \u0628\u0627 \u062f\u0633\u062a\u06af\u0627\u0647 \u0698\u0646\u06cc\u062a\u0627\u0644 \u0648 \u062a\u0635\u0648\u06cc\u0631 \u0637\u0628\u06cc\u0639\u06cc \u0648 TSH/PRL \u0637\u0628\u06cc\u0639\u06cc: \u0642\u062f\u0645 \u0628\u0639\u062f\u06cc \u0627\u0646\u062f\u0627\u0632\u0647\u200c\u06af\u06cc\u0631\u06cc LH \u0648 FSH \u0628\u0631\u0627\u06cc \u062a\u0641\u06a9\u06cc\u06a9 \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u062a\u062e\u0645\u062f\u0627\u0646 (\u0647\u0627\u06cc\u067e\u0631\u06af\u0646\u0627\u062f\u0648\u062a\u0631\u0648\u067e) \u0627\u0632 \u0628\u0647 \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u0645\u0631\u06a9\u0632\u06cc (\u0647\u06cc\u067e\u0648\u06af\u0646\u0627\u062f\u0648\u062a\u0631\u0648\u067e).",
   "interpretation": "\u062f\u0631 \u0622\u0645\u0646\u0648\u0631\u0647\u0654 \u0627\u0648\u0644\u06cc\u0647\u060c \u0627\u0648\u0644\u06cc\u0646 \u0644\u0627\u06cc\u0647\u0654 \u062a\u0641\u06a9\u06cc\u06a9 \u067e\u0633 \u0627\u0632 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0622\u0646\u0627\u062a\u0648\u0645\u06cc \u0648 \u062d\u0630\u0641 \u0639\u0644\u0644 \u067e\u0631\u0648\u0644\u0627\u06a9\u062a\u06cc\u0646\u06cc/\u062a\u06cc\u0631\u0648\u0626\u06cc\u062f\u06cc\u060c \u0633\u0646\u062c\u0634 \u06af\u0646\u0627\u062f\u0648\u062a\u0631\u0648\u067e\u06cc\u0646\u200c\u0647\u0627 \u0627\u0633\u062a: FSH/LH \u0628\u0627\u0644\u0627 \u0646\u0634\u0627\u0646\u0647\u0654 \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u0627\u0648\u0644\u06cc\u0647\u0654 \u062a\u062e\u0645\u062f\u0627\u0646 (\u0648 \u06a9\u0627\u0631\u06cc\u0648\u062a\u0627\u06cc\u067e \u067e\u0644\u0647\u0654 \u0628\u0639\u062f\u06cc \u0627\u0633\u062a) \u0648 \u067e\u0627\u06cc\u06cc\u0646 \u0645\u0639\u0637\u0648\u0641 \u0628\u0647 \u0645\u062d\u0648\u0631 \u0647\u06cc\u067e\u0648\u062a\u0627\u0644\u0627\u0645\u0648\u0633-\u0647\u06cc\u067e\u0648\u0641\u06cc\u0632 (MRI \u0645\u063a\u0632 \u067e\u0644\u0647\u0654 \u0628\u0639\u062f\u06cc)\u061b \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u062f\u0631 \u0627\u06cc\u0646 \u0628\u06cc\u0645\u0627\u0631 \u0628\u0627 \u062f\u0633\u062a\u06af\u0627\u0647 \u0698\u0646\u06cc\u062a\u0627\u0644 \u0637\u0628\u06cc\u0639\u06cc \u0648 TSH/PRL \u0637\u0628\u06cc\u0639\u06cc\u060c \u0633\u0646\u062c\u0634 LH/FSH \u0645\u0646\u0637\u0642\u06cc\u200c\u062a\u0631\u06cc\u0646 \u0642\u062f\u0645 \u0628\u0639\u062f\u06cc \u0627\u0633\u062a.",
   "reasons": ["CT \u0644\u06af\u0646 \u0628\u0631\u0627\u06cc \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0639\u0644\u0644 \u0622\u0645\u0646\u0648\u0631\u0647 \u062f\u0631 \u0627\u06cc\u0646 \u0645\u0631\u062d\u0644\u0647 \u0627\u0631\u0632\u0634 \u0627\u0641\u0632\u0648\u062f\u0647 \u0646\u062f\u0627\u0631\u062f.", "MRI \u0645\u063a\u0632 \u0628\u0639\u062f\u0627\u064b \u0648 \u0628\u0631 \u0627\u0633\u0627\u0633 \u0633\u0637\u062d \u06af\u0646\u0627\u062f\u0648\u062a\u0631\u0648\u067e\u06cc\u0646\u200c\u0647\u0627 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0627\u0646\u062f\u0627\u0632\u0647\u200c\u06af\u06cc\u0631\u06cc LH/FSH \u0642\u062f\u0645 \u0635\u062d\u06cc\u062d \u0628\u0639\u062f\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u06a9\u0627\u0631\u06cc\u0648\u062a\u0627\u06cc\u067e \u067e\u0633 \u0627\u0632 FSH \u062a\u0635\u0645\u06cc\u0645\u200c\u0633\u0627\u0632 \u0627\u0633\u062a \u0646\u0647 \u0628\u0647\u200c\u0639\u0646\u0648\u0627\u0646 \u062a\u0633\u062a \u0627\u0648\u0644."],
  },
  (28, 123): {
   "topic": "ocpAllowedWithCaution",
   "lead": "\u062f\u0631 \u0645\u06cc\u0627\u0646 \u0627\u06cc\u0646 \u0641\u0647\u0631\u0633\u062a\u060c \u062a\u0646\u0647\u0627 \u0648\u0636\u0639\u06cc\u062a \u0633\u0627\u0632\u06af\u0627\u0631 \u0628\u0627 \u062a\u062c\u0648\u06cc\u0632 OCP \u0628\u0627 \u067e\u0627\u06cc\u0634 \u062f\u0642\u06cc\u0642 \u00ab\u0633\u0627\u0628\u0642\u0647\u0654 \u06a9\u0644\u0647\u200c\u0633\u06cc\u0633\u062a\u06a9\u062a\u0648\u0645\u06cc\u00bb \u0627\u0633\u062a\u061b DVT \u0633\u0627\u0628\u0642\u0647\u060c \u0647\u0645\u0627\u0646\u0698\u06cc\u0648\u0645 \u06a9\u0628\u062f\u06cc \u0648 \u0628\u06cc\u200c\u062d\u0631\u06a9\u062a\u06cc \u067e\u0633 \u0627\u0632 \u0634\u06a9\u0633\u062a\u06af\u06cc \u0644\u06af\u0646 \u0628\u0627 OCP \u062e\u0637\u0631\u0646\u0627\u06a9 \u0627\u0633\u062a.",
   "interpretation": "\u0645\u0646\u0639\u200c\u0647\u0627\u06cc \u062c\u062f\u06cc OCP \u0634\u0627\u0645\u0644 \u0633\u0627\u0628\u0642\u0647\u0654 \u062a\u0631\u0648\u0645\u0628\u0648\u0622\u0645\u0628\u0648\u0644\u06cc \u0648\u0631\u06cc\u062f\u06cc\u060c \u0628\u06cc\u0645\u0627\u0631\u06cc \u0641\u0639\u0627\u0644 \u06a9\u0628\u062f (\u0647\u0645\u0627\u0646\u0698\u06cc\u0648\u0645 \u0646\u06cc\u0632 \u062f\u0631 \u0641\u0647\u0631\u0633\u062a \u0627\u062d\u062a\u06cc\u0627\u0637/\u0645\u0646\u0639 \u0628\u0631\u062e\u06cc \u0631\u0627\u0647\u0646\u0645\u0627\u0647\u0627) \u0648 \u0628\u06cc\u200c\u062d\u0631\u06a9\u062a\u06cc/\u062f\u0648\u0631\u0647\u0654 \u062e\u0637\u0631 \u062a\u0631\u0648\u0645\u0628\u0648\u0632 \u0627\u0633\u062a\u061b \u0633\u0627\u0628\u0642\u0647\u0654 \u0633\u0646\u0628\u0644\u0647/\u06a9\u0644\u0647\u200c\u0633\u06cc\u0633\u062a\u06a9\u062a\u0648\u0645\u06cc (\u0628\u0631\u062f\u0627\u0634\u062a\u0646 \u06a9\u06cc\u0633\u0647\u0654 \u0635\u0641\u0631\u0627) \u0646\u0647 \u0628\u0647\u200c\u062e\u0648\u062f\u06cc\u200c\u062e\u0648\u062f \u0645\u0646\u0639 \u0627\u0633\u062a \u0648\u0644\u06cc \u0645\u0633\u062a\u0644\u0632\u0645 \u067e\u0627\u06cc\u0634 \u0639\u0645\u0644\u06a9\u0631\u062f \u06a9\u0628\u062f \u0627\u0633\u062a \u0648 \u00ab\u0628\u0627 \u0646\u0638\u0627\u0631\u062a \u062f\u0642\u06cc\u0642\u00bb \u0628\u0627 \u0622\u0646 \u0633\u0627\u0632\u06af\u0627\u0631 \u0627\u0633\u062a.",
   "reasons": ["\u0633\u0627\u0628\u0642\u0647\u0654 \u0627\u0646\u0633\u062f\u0627\u062f \u0648\u0631\u06cc\u062f \u0639\u0645\u0642\u06cc \u0628\u0627 \u0642\u0631\u0635 \u062a\u0631\u06a9\u06cc\u0628\u06cc \u0645\u0646\u0639 \u0645\u0635\u0631\u0641 \u0645\u0637\u0644\u0642 \u0627\u0633\u062a.", "\u0647\u0645\u0627\u0646\u0698\u06cc\u0648\u0645 \u06a9\u0628\u062f\u06cc \u062f\u0631 \u0641\u0647\u0631\u0633\u062a \u0627\u062d\u062a\u06cc\u0627\u0637/\u0645\u0646\u0639 OCP \u0642\u0631\u0627\u0631 \u0645\u06cc\u200c\u06af\u06cc\u0631\u062f.", "\u0628\u06cc\u200c\u062d\u0631\u06a9\u062a\u06cc \u067e\u0633 \u0627\u0632 \u0634\u06a9\u0633\u062a\u06af\u06cc \u0644\u06af\u0646 \u0628\u0627 OCP \u062e\u0637\u0631 \u062a\u0631\u0648\u0645\u0628\u0648\u0632 \u0631\u0627 \u0632\u06cc\u0627\u062f \u0645\u06cc\u200c\u06a9\u0646\u062f.", "\u0633\u0627\u0628\u0642\u0647\u0654 \u06a9\u0644\u0647\u200c\u0633\u06cc\u0633\u062a\u06a9\u062a\u0648\u0645\u06cc \u0634\u062f\u06cc\u062f \u0646\u06cc\u0633\u062a \u0648 \u0628\u0627 \u067e\u0627\u06cc\u0634 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646 OCP \u062f\u0627\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 124): {
   "topic": "severePreeclampsiaFeatures",
   "lead": "\u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0634\u062f\u06cc\u062f \u06f3\u06f5 \u0647\u0641\u062a\u0647 \u0628\u0627 \u067e\u0644\u0627\u06a9\u062a \u06f8\u06f0 \u0647\u0632\u0627\u0631\u060c \u0622\u0646\u0632\u06cc\u0645\u200c\u0647\u0627\u06cc \u06a9\u0628\u062f\u06cc \u0686\u0646\u062f\u0628\u0631\u0627\u0628\u0631 \u0648 \u0627\u0644\u06cc\u06af\u0648\u0631\u06cc \u06f3\u06f0\u06f0 \u0633\u06cc\u200c\u0633\u06cc/\u06f2\u06f4 \u0633\u0627\u0639\u062a: \u062a\u0635\u0645\u06cc\u0645 \u0642\u0637\u0639\u06cc \u062e\u062a\u0645 \u0641\u0648\u0631\u06cc \u0628\u0627\u0631\u062f\u0627\u0631\u06cc (\u0628\u0647 \u0647\u0645\u0631\u0627\u0647 \u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645/\u06a9\u0648\u0631\u062a\u0648\u0646) \u0646\u0647 \u0646\u06af\u0647\u200c\u062f\u0627\u0634\u062a\u0646 \u0628\u0647 \u0645\u0646\u0638\u0648\u0631 \u0628\u0644\u0648\u063a \u0631\u06cc\u0647.",
   "interpretation": "\u0686\u0646\u062f\u0645\u0639\u06cc\u0627\u0631\u06cc \u0634\u062f\u06cc\u062f \u0647\u0645\u200c\u0632\u0645\u0627\u0646 (\u0641\u0634\u0627\u0631 \u06f1\u06f6\u06f0/\u06f1\u06f1\u06f0\u060c \u062a\u0631\u0648\u0645\u0628\u0648\u0633\u06cc\u062a\u0648\u067e\u0646\u06cc <\u06f1\u06f0\u06f0\u06f0\u06f0\u06f0\u060c \u0627\u0641\u0632\u0627\u06cc\u0634 \u0622\u0646\u0632\u06cc\u0645\u200c\u0647\u0627\u06cc \u06a9\u0628\u062f\u06cc \u0648 \u06a9\u0627\u0647\u0634 \u062d\u062c\u0645 \u0627\u062f\u0631\u0627\u0631 \u0646\u0634\u0627\u0646\u06af\u0631 \u0622\u0633\u06cc\u0628 \u06a9\u0644\u06cc\u0648\u06cc) \u062f\u0631 \u06f3\u06f5 \u0647\u0641\u062a\u0647\u060c \u062a\u0639\u062c\u06cc\u0644 \u062f\u0631 \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0631\u0627 \u0645\u06cc\u200c\u0637\u0644\u0628\u062f \u0648 \u0627\u0646\u062a\u0638\u0627\u0631 \u0628\u0631 \u0627\u0633\u0627\u0633 \u06a9\u0648\u0631\u062a\u0648\u0646 \u0628\u0647\u200c\u0637\u0648\u0631 \u062f\u06cc\u0631\u0631\u0633 \u06f4\u06f8 \u0633\u0627\u0639\u062a\u0647\u060c \u062e\u0637\u0631 \u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0648 \u0627\u062e\u062a\u0644\u0627\u0644 \u0639\u0645\u0644\u06a9\u0631\u062f \u0627\u0631\u06af\u0627\u0646 \u0631\u0627 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f\u061b \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0628\u06cc\u0648\u0641\u06cc\u0632\u06cc\u06a9\u0627\u0644 \u06af\u0632\u0627\u0631\u0634 \u0648\u0636\u0639 \u062c\u0646\u06cc\u0646\u06cc \u0645\u06cc\u200c\u062f\u0647\u062f \u0648\u0644\u06cc \u0645\u0633\u06cc\u0631 \u062a\u0635\u0645\u06cc\u0645\u200c\u06af\u06cc\u0631\u06cc \u0645\u0627\u062f\u0631 \u0631\u0627 \u0639\u0648\u0636 \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u062f\u0627\u0631\u0648\u0647\u0627\u06cc \u0641\u0634\u0627\u0631+\u062f\u06cc\u0648\u0631\u062a\u06cc\u06a9 \u062c\u0627\u06cc \u062e\u062a\u0645 \u0642\u0637\u0639\u06cc \u0631\u0627 \u0646\u0645\u06cc\u200c\u06af\u06cc\u0631\u062f.",
   "reasons": ["\u062a\u062c\u0648\u06cc\u0632 \u0627\u0633\u062a\u0631\u0648\u0626\u06cc\u062f \u0648 \u062a\u0639\u0644\u0644 \u06f4\u06f8 \u0633\u0627\u0639\u062a\u0647 \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0637\u062d \u0639\u0644\u0627\u06cc\u0645 \u0634\u062f\u06cc\u062f \u0627\u0634\u062a\u0628\u0627\u0647 \u0627\u0633\u062a.", "BPP \u062f\u0631 \u062a\u0635\u0645\u06cc\u0645 \u0645\u0627\u062f\u0631 \u062f\u0631 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0634\u062f\u06cc\u062f \u0646\u0642\u0634 \u062a\u0639\u06cc\u06cc\u0646\u200c\u06a9\u0646\u0646\u062f\u0647 \u0646\u062f\u0627\u0631\u062f.", "\u062e\u062a\u0645 \u0641\u0648\u0631\u06cc \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0631 \u0686\u0646\u062f\u0639\u0644\u0627\u0645\u062a\u06cc \u0634\u062f\u06cc\u062f \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0633\u06cc\u200c\u0646\u0642\u0644 \u0641\u0634\u0627\u0631 \u0648 \u062f\u06cc\u0648\u0631\u062a\u06cc\u06a9 \u062c\u0627\u06cc \u062e\u062a\u0645 \u0631\u0627 \u0646\u0645\u06cc\u200c\u06af\u06cc\u0631\u062f."],
  },
  (28, 125): {
   "topic": "fibroidFeaturesExcept",
   "lead": "\u0641\u06cc\u0628\u0631\u0648\u0645\u200c\u0647\u0627\u06cc \u0631\u062d\u0645\u06cc \u0628\u06cc\u0634\u200c\u062a\u0631 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0631\u0627 \u0628\u0647\u200c\u0635\u0648\u0631\u062a \u00ab\u0645\u0646\u0648\u0631\u0627\u0698\u06cc\u00bb \u0627\u0641\u0632\u0627\u06cc\u0634 \u0645\u06cc\u200c\u062f\u0647\u0646\u062f \u0648 \u0627\u0644\u06cc\u06af\u0648\u0645\u0646\u0648\u0631\u0647 \u062c\u0632\u0648 \u0627\u062b\u0631\u0647\u0627\u06cc \u0645\u0639\u0645\u0648\u0644 \u0622\u0646\u200c\u0647\u0627 \u0646\u06cc\u0633\u062a.",
   "interpretation": "\u0627\u0646\u0648\u0627\u0639 \u0645\u06cc\u0648\u0645 \u0628\u0631 \u0627\u0633\u0627\u0633 \u0645\u0648\u0642\u0639\u06cc\u062a (\u0633\u0627\u0628\u200c\u0645\u0648\u06a9\u0648\u0632\u0627\u0644/\u0627\u06cc\u0646\u062a\u0631\u0627\u0645\u0648\u0631\u0627\u0644/\u0633\u0627\u0628\u200c\u0633\u0631\u0648\u0632\u0627\u0644) \u0627\u062b\u0631\u0647\u0627\u06cc \u0645\u062a\u0641\u0627\u0648\u062a \u062f\u0627\u0631\u0646\u062f\u061b \u0633\u0627\u0628\u200c\u0645\u0648\u06a9\u0648\u0632\u0627\u0644 \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u0646\u0632\u062f\u06cc\u06a9\u06cc \u0628\u0647 \u062d\u0641\u0631\u0647\u0654 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0628\u06cc\u0634\u200c\u062a\u0631\u06cc\u0646 \u0627\u062b\u0631 \u0628\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0648 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0631\u0627 \u062f\u0627\u0631\u062f \u0648 \u0645\u06cc\u0648\u0645 \u0628\u0627 \u0645\u0646\u0648\u0631\u0627\u0698\u06cc (\u0646\u0647 \u0627\u0644\u06cc\u06af\u0648\u0645\u0646\u0648\u0631\u0647) \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a\u061b \u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633\u060c \u0627\u0636\u0637\u0631\u0627\u0628 \u0627\u0648\u0644\u06cc\u0647 \u0648 \u062f\u0698\u0646\u0631\u0627\u0633\u06cc\u0648\u0646 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc (\u06a9\u0647 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0628\u0627 \u062c\u0631\u0627\u062d\u06cc \u0641\u0648\u0631\u06cc \u0646\u06cc\u0627\u0632\u06cc \u0646\u06cc\u0633\u062a) \u0627\u0632 \u067e\u06cc\u0627\u0645\u062f\u0647\u0627\u06cc \u0634\u0646\u0627\u062e\u062a\u0647\u200c\u0634\u062f\u0647\u0654 \u0645\u06cc\u0648\u0645 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u0633\u062a.",
   "reasons": ["\u0641\u06cc\u0628\u0631\u0648\u0645 \u0633\u0627\u0628\u200c\u0645\u0648\u06a9\u0648\u0632\u0627\u0644 \u0628\u06cc\u0634\u200c\u062a\u0631\u06cc\u0646 \u0627\u062b\u0631 \u0631\u0627 \u0628\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0627\u0631\u062f \u0648 \u062f\u0631\u0633\u062a \u0627\u0633\u062a.", "\u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633 \u0627\u0632 \u0639\u0648\u0627\u0631\u0636 \u062d\u0627\u0645\u0644\u06af\u06cc \u0628\u0627 \u0641\u06cc\u0628\u0631\u0648\u0645 \u0627\u0633\u062a \u0648 \u062f\u0631\u0633\u062a \u0627\u0633\u062a.", "\u0627\u0644\u06cc\u06af\u0648\u0645\u0646\u0648\u0631\u0647 \u0627\u062b\u0631 \u0645\u0639\u0645\u0648\u0644 \u0641\u06cc\u0628\u0631\u0648\u0645 \u0646\u06cc\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d (\u00ab\u0635\u062d\u06cc\u062d \u0646\u06cc\u0633\u062a\u00bb).", "\u062f\u0698\u0646\u0631\u0633\u0627\u0646\u0633 \u0641\u06cc\u0628\u0631\u0648\u0645 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0641\u0648\u0631\u06cc\u062a \u062c\u0631\u0627\u062d\u06cc \u0646\u062f\u0627\u0631\u062f."],
  },
  (28, 126): {
   "topic": "posScreenAmnio",
   "lead": "\u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0645\u062b\u0628\u062a \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0627\u0648\u0644: \u0645\u0631\u062d\u0644\u0647\u0654 \u0628\u0639\u062f\u06cc \u0622\u0632\u0645\u0648\u0646 \u062a\u0634\u062e\u06cc\u0635\u06cc (\u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u062a\u0647\u0627\u062c\u0645\u06cc) \u0627\u0633\u062a \u0648 \u062f\u0631 \u0686\u0627\u0631\u0686\u0648\u0628 \u06a9\u0644\u0627\u0633\u06cc\u06a9 \u0627\u06cc\u0646 \u0633\u0624\u0627\u0644 \u0622\u0645\u0646\u06cc\u0648\u0633\u0646\u062a\u0632 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0644\u06cc\u062f \u0627\u0633\u062a.",
   "interpretation": "\u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0645\u062b\u0628\u062a \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0627\u0648\u0644 \u0628\u0647 \u0645\u0639\u0646\u0627\u06cc \u062a\u062e\u0645\u06cc\u0646 \u0628\u0627\u0644\u0627\u06cc \u062e\u0637\u0631 \u06a9\u0631\u0648\u0645\u0648\u0632\u0648\u0645\u06cc \u0627\u0633\u062a \u0648 \u0628\u0627\u06cc\u062f \u0628\u0627 \u0622\u0632\u0645\u0648\u0646 \u062a\u0634\u062e\u06cc\u0635\u06cc \u0642\u0637\u0639\u06cc \u062f\u0646\u0628\u0627\u0644 \u0634\u0648\u062f\u061b \u062f\u0631 \u0645\u0646\u0627\u0628\u0639 \u0645\u0631\u062c\u0639 \u06a9\u0644\u0627\u0633\u06cc\u06a9\u060c \u00ab\u0622\u0645\u0646\u06cc\u0648\u0633\u0646\u062a\u0632\u00bb \u062f\u0631 \u067e\u0646\u062c\u0631\u0647\u0654 \u06f1\u06f5-\u06f2\u06f0 \u0647\u0641\u062a\u0647 \u0631\u0648\u0634 \u062a\u0634\u062e\u06cc\u0635\u06cc \u062a\u0639\u06cc\u06cc\u0646\u200c\u0634\u062f\u0647\u0654 \u0631\u0627\u06cc\u062c \u0645\u062d\u0633\u0648\u0628 \u0645\u06cc\u200c\u0634\u0648\u062f (CVS \u0641\u0642\u0637 \u062f\u0631 \u0628\u0627\u0632\u0647\u0654 \u06f1\u06f0 \u062a\u0627 \u06f1\u06f3 \u0647\u0641\u062a\u0647 \u0648 \u06f6 \u0631\u0648\u0632 \u0642\u0627\u0628\u0644 \u0627\u062c\u0631\u0627\u0633\u062a \u0648 \u0628\u0627 \u062a\u0648\u062c\u0647 \u0628\u0647 \u0632\u0645\u0627\u0646 \u0627\u0631\u062c\u0627\u0639 \u0645\u0634\u062e\u0635\u200c\u0634\u062f\u0647 \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646\u0627\u0631\u06cc\u0648\u060c \u0622\u0645\u0646\u06cc\u0648\u0633\u0646\u062a\u0632 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0644\u06cc\u062f \u0627\u0633\u062a)\u061b \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628 \u0628\u0647\u200c\u062c\u0627\u06cc \u067e\u06cc\u06af\u06cc\u0631\u06cc \u062a\u0634\u062e\u06cc\u0635\u06cc \u0628\u0627 \u0627\u0631\u062c\u0627\u0639 \u0645\u0634\u0627\u0648\u0631\u0647\u0654 \u0698\u0646\u062a\u06cc\u06a9 \u0639\u062c\u0648\u0644\u0627\u0646\u0647 \u0627\u0633\u062a \u0648 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0622\u0646\u0648\u0645\u0627\u0644\u06cc \u0645\u06a9\u0645\u0644 \u0627\u0633\u062a \u0646\u0647 \u062c\u0627\u06cc\u06af\u0632\u06cc\u0646.",
   "reasons": ["\u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0641\u0642\u0637 \u0628\u0627 \u062a\u0633\u062a \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0645\u062b\u0628\u062a \u063a\u06cc\u0631\u0627\u0635\u0648\u0644\u06cc \u0627\u0633\u062a.", "\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u062f\u0642\u06cc\u0642 \u0645\u06a9\u0645\u0644 \u0627\u0633\u062a \u0646\u0647 \u062c\u0627\u06cc\u06af\u0632\u06cc\u0646 \u0622\u0632\u0645\u0648\u0646 \u062a\u0634\u062e\u06cc\u0635\u06cc.", "\u0622\u0645\u0646\u06cc\u0648\u0633\u0646\u062a\u0632 \u0631\u0648\u0634 \u062a\u0634\u062e\u06cc\u0635\u06cc \u062a\u0639\u06cc\u06cc\u0646\u200c\u0634\u062f\u0647\u0654 \u06a9\u0644\u06cc\u062f \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "CVS \u0641\u0642\u0637 \u062f\u0631 \u0628\u0627\u0632\u0647\u0654 \u0627\u0648\u0644\u06cc\u0647\u0654 \u0645\u0634\u062e\u0635 \u0642\u0627\u0628\u0644\u200c\u0628\u062d\u062b \u0627\u0633\u062a."],
  },
  (28, 127): {
   "topic": "pregnancyVaccines",
   "lead": "\u0633\u0631\u062e\u062c\u0647 (\u0628\u062e\u0634\u06cc \u0627\u0632 MMR) \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a\u061b \u0647\u067e\u0627\u062a\u06cc\u062a B\u060c \u0622\u0646\u0641\u0644\u0648\u0622\u0646\u0632\u0627 \u0648 \u06a9\u0632\u0627\u0632/\u062a\u062a\u0627\u0646\u0648\u0633 \u063a\u06cc\u0631\u0632\u0646\u062f\u0647\u200c\u0627\u0646\u062f \u0648 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0627 \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u0645\u062c\u0627\u0632\u0646\u062f.",
   "interpretation": "\u0648\u0627\u06a9\u0633\u0646\u200c\u0647\u0627\u06cc \u0632\u0646\u062f\u0647\u0654 \u062a\u0636\u0639\u06cc\u0641\u200c\u0634\u062f\u0647 (\u0633\u0631\u062e\u062c\u0647/\u0627\u0648\u0631\u06cc\u0648\u0646 MMR\u060c \u0648\u0627\u0631\u06cc\u0633\u0644\u0627 \u0648 \u062a\u0628 \u0632\u0631\u062f) \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u062e\u0637\u0631 \u0646\u0638\u0631\u06cc \u0639\u0641\u0648\u0646\u062a \u062c\u0646\u06cc\u0646\u06cc \u0645\u0645\u0646\u0648\u0639\u200c\u0627\u0646\u062f\u061b \u0647\u067e\u0627\u062a\u06cc\u062a B (\u067e\u0631\u0648\u062a\u0626\u06cc\u0646\u06cc)\u060c \u0622\u0646\u0641\u0644\u0648\u0622\u0646\u0632\u0627\u06cc \u06a9\u0634\u062a\u0647\u200c\u0634\u062f\u0647\u0654 \u062a\u0632\u0631\u06cc\u0642\u06cc \u0648 \u0648\u0627\u06a9\u0633\u0646 \u062a\u0631\u06a9\u06cc\u0628 \u06a9\u0632\u0627\u0632-\u062f\u06cc\u0641\u062a\u0631\u06cc \u0627\u0632 \u06af\u0631\u0648\u0647 \u063a\u06cc\u0631\u0632\u0646\u062f\u0647\u200c\u0627\u0646\u062f \u0648 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0631 \u0635\u0648\u0631\u062a \u0646\u06cc\u0627\u0632 \u0645\u062c\u0627\u0632\u0646\u062f \u0648 \u0645\u062b\u0644 \u06a9\u0632\u0627\u0632 \u062d\u062a\u06cc \u0641\u0639\u0627\u0644 \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f.",
   "reasons": ["\u0647\u067e\u0627\u062a\u06cc\u062a B \u0648\u0627\u06a9\u0633\u0646 \u063a\u06cc\u0631\u0632\u0646\u062f\u0647 \u0627\u0633\u062a \u0648 \u0628\u0627 \u062e\u0637\u0631 \u0645\u062c\u0627\u0632 \u0627\u0633\u062a.", "\u0622\u0646\u0641\u0644\u0648\u0622\u0646\u0632\u0627 \u0641\u0635\u0644\u06cc \u06a9\u0634\u062a\u0647\u200c\u0634\u062f\u0647\u0654 \u062a\u0632\u0631\u06cc\u0642\u06cc \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0633\u0631\u062e\u062c\u0647 \u0648\u0627\u06a9\u0633\u0646 \u0632\u0646\u062f\u0647 \u0627\u0633\u062a \u0648 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0645\u0646\u0648\u0639\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u06a9\u0632\u0627\u0632/\u062a\u062a\u0627\u0646\u0648\u0633 \u0648 \u062f\u06cc\u0641\u062a\u0631\u06cc \u063a\u06cc\u0631\u0632\u0646\u062f\u0647 \u0627\u0633\u062a \u0648 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u062c\u0627\u0632 \u0627\u0633\u062a."],
  },
  (28, 128): {
   "topic": "pretermLaborBundle",
   "lead": "\u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633 \u0628\u0627 \u062a\u063a\u06cc\u06cc\u0631 \u0633\u0631\u0648\u06cc\u06a9\u0633 (\u0627\u0646\u0642\u0628\u0627\u0636 \u06f2\u00d7 \u062f\u0631 \u06f2\u06f0 \u062f\u0642\u06cc\u0642\u0647 + \u062f\u06cc\u0644\u0627\u062a\u0627\u0633\u06cc\u0648\u0646 \u06f2 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631 + \u0627\u0641\u0627\u0633\u0645\u0627\u0646 \u06f8\u06f0\u066a): \u0628\u0633\u062a\u0631\u06cc + \u062a\u0648\u06a9\u0648\u0644\u06cc\u062a\u06cc\u06a9 + \u06a9\u0648\u0631\u062a\u0648\u0646 \u0628\u0631\u0627\u06cc \u0628\u0647 \u062a\u0639\u0648\u06cc\u0642 \u0627\u0646\u062f\u0627\u062e\u062a\u0646 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0648 \u0628\u0644\u0648\u063a \u0631\u06cc\u0647.",
   "interpretation": "\u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633 \u0648\u0627\u0642\u0639\u06cc \u0628\u0627 \u0627\u0646\u0642\u0628\u0627\u0636\u200c\u0647\u0627\u06cc \u0645\u0624\u06cc\u062f \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u062a\u063a\u06cc\u06cc\u0631 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0648\u0642\u062a\u06cc \u062c\u0646\u06cc\u0646 \u0642\u0627\u0628\u0644 \u0646\u062c\u0627\u062a \u0628\u0627\u0634\u062f\u060c \u0628\u0627\u06cc\u062f \u0628\u0627 \u0628\u0633\u062a\u0631\u06cc\u060c \u062a\u0648\u06a9\u0648\u0644\u06cc\u062a\u06cc\u06a9 \u06a9\u0648\u062a\u0627\u0647\u200c\u0645\u062f\u062a (\u0645\u062b\u0644 \u0646\u06cc\u0641\u06cc\u062f\u06cc\u067e\u06cc\u0646/\u0627\u06cc\u0646\u062f\u0648\u0645\u062a\u0627\u0633\u06cc\u0646) \u0648 \u0628\u062a\u0627\u0645\u062a\u0627\u0632\u0648\u0646/\u062f\u06af\u0632\u0627\u0645\u062a\u0627\u0632\u0648\u0646 \u0628\u0631\u0627\u06cc \u0628\u0644\u0648\u063a \u0631\u06cc\u0647 \u0645\u062f\u06cc\u0631\u06cc\u062a \u0634\u0648\u062f \u0648 \u062f\u0631 \u0635\u0648\u0631\u062a \u0639\u0641\u0648\u0646\u062a \u06cc\u0627 \u0646\u0627\u067e\u0627\u06cc\u062f\u0627\u0631\u06cc \u0645\u0633\u06cc\u0631 \u0645\u062a\u0641\u0627\u0648\u062a \u062e\u0648\u0627\u0647\u062f \u0634\u062f\u061b \u062e\u062a\u0645 \u0641\u0648\u0631\u06cc\u062a \u06cc\u0627 \u062f\u0631\u0645\u0627\u0646 \u0633\u0631\u067e\u0627\u06cc\u06cc \u0628\u0627 \u0627\u06cc\u0646 \u0645\u06cc\u0632\u0627\u0646 \u062a\u063a\u06cc\u06cc\u0631 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0639\u062c\u0648\u0644\u0627\u0646\u0647 \u0648 \u0646\u0627\u06a9\u0627\u0641\u06cc \u0627\u0633\u062a.",
   "reasons": ["\u0633\u0631\u06a9\u0644\u0627\u0698 \u062f\u0631 \u062d\u0636\u0648\u0631 \u0627\u0646\u0642\u0628\u0627\u0636 \u0641\u0639\u0627\u0644 \u067e\u0633 \u0627\u0632 \u0634\u0631\u0648\u0639 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633 \u0645\u0646\u0639 \u0627\u0633\u062a.", "\u06a9\u0648\u0631\u062a\u0648\u0646+\u062e\u062a\u0645 \u0628\u0644\u0627\u0641\u0627\u0635\u0644\u0647 \u062f\u0631 \u063a\u06cc\u0627\u0628 \u0639\u0644\u062a \u062e\u0627\u0635 \u0627\u0634\u062a\u0628\u0627\u0647 \u0627\u0633\u062a.", "\u062f\u0631\u0645\u0627\u0646 \u0633\u0631\u067e\u0627\u06cc\u06cc \u0639\u0641\u0648\u0646\u062a \u0627\u062f\u0631\u0627\u0631\u06cc \u06a9\u0627\u0631\u0622\u067e \u0627\u06cc\u0646 \u0633\u0646\u0627\u0631\u06cc\u0648 \u0646\u06cc\u0633\u062a.", "\u0628\u0633\u062a\u0631\u06cc + \u062a\u0648\u06a9\u0648\u0644\u06cc\u062a\u06cc\u06a9 + \u06a9\u0648\u0631\u062a\u0648\u0646 \u067e\u0627\u0633\u062e \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 129): {
   "topic": "\u0633\u06cc\u0641\u0644\u06cc\u0633ScreenConfirm",
   "lead": "\u062f\u0631 \u0645\u062a\u0646 \u0628\u0631\u0646\u0627\u0645\u0647\u0654 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0628\u0627\u0631\u062f\u0627\u0631\u06cc\u060c VDRL \u0645\u062b\u0628\u062a \u0639\u0646\u0648\u0627\u0646 \u062f\u0648 \u0642\u062f\u0645 \u0627\u0633\u062a: \u0627\u0628\u062a\u062f\u0627 \u062a\u0623\u06cc\u06cc\u062f \u0628\u0627 \u0622\u0632\u0645\u0648\u0646 \u0627\u062e\u062a\u0635\u0627\u0635\u06cc \u062a\u0631\u067e\u0648\u0646\u0645\u0627\u06cc\u06cc (FTA-Abs) \u0633\u067e\u0633 \u062a\u0639\u06cc\u06cc\u0646 \u0648\u0636\u0639\u06cc\u062a \u062f\u0631\u0645\u0627\u0646.",
   "interpretation": "\u0645\u062b\u0644\u062b \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0633\u06cc\u0641\u0644\u06cc\u0633 \u062f\u0648\u06af\u0627\u0646\u0647 \u0627\u0633\u062a: \u062a\u0633\u062a\u200c\u0647\u0627\u06cc \u063a\u06cc\u0631\u062a\u0631\u067e\u0648\u0646\u0645\u0627\u06cc\u06cc (VDRL/RPR) \u062d\u0633\u0627\u0633 \u0648 \u062a\u0633\u062a\u200c\u0647\u0627\u06cc \u062a\u0631\u067e\u0648\u0646\u0645\u0627\u06cc\u06cc (FTA-Abs/TPHA) \u0627\u062e\u062a\u0635\u0627\u0635\u06cc \u062a\u0623\u06cc\u06cc\u062f \u0647\u0633\u062a\u0646\u062f \u0648 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0627 \u062f\u0631\u062f \u0628\u0647\u200c\u0639\u0646\u0648\u0627\u0646 \u0639\u0644\u062a \u0648 \u0628\u0627 \u062a\u0635\u0645\u06cc\u0645 \u062f\u0631\u0645\u0627\u0646\u06cc \u0645\u0633\u062a\u0642\u06cc\u0645 (\u06a9\u0647 \u0647\u0645\u06cc\u0634\u0647 \u067e\u0646\u06cc\u200c\u0633\u06cc\u0644\u06cc\u0646 \u0627\u0633\u062a) \u0645\u0642\u0635\u062f \u0627\u0633\u062a\u061b \u062f\u0631 \u0639\u0645\u0644\u060c \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u06af\u0631 VDRL \u0645\u062b\u0628\u062a \u0634\u0648\u062f\u060c \u062a\u0623\u06cc\u06cc\u062f \u0627\u062e\u062a\u0635\u0627\u0635\u06cc \u0648 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0628\u0627\u0644\u06cc\u0646\u06cc \u0641\u0648\u0631\u06cc \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f (\u0648 \u062f\u0631 \u0628\u0633\u06cc\u0627\u0631\u06cc \u0627\u0632 \u0634\u06cc\u0648\u0647\u200c\u0647\u0627\u06cc \u0648\u0627\u0642\u0639\u06cc \u062f\u0631\u0645\u0627\u0646 \u0634\u0631\u0648\u0639 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648\u0644\u06cc \u06a9\u0644\u06cc\u062f \u0627\u06cc\u0646 \u067e\u0631\u0633\u0634 \u0645\u0631\u062d\u0644\u0647\u0654 \u062a\u0623\u06cc\u06cc\u062f \u0631\u0627 \u0627\u0648\u0644 \u0645\u06cc\u200c\u0686\u06cc\u0646\u062f) \u0648 \u0627\u0631\u06cc\u062a\u0631\u0648\u0645\u0627\u06cc\u0633\u06cc\u0646 \u062f\u0631 \u0627\u06cc\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u06af\u0632\u06cc\u0646\u0647\u0654 \u0645\u0646\u0627\u0633\u0628 \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0628\u0631\u0631\u0633\u06cc \u0633\u0627\u06cc\u0631 \u0639\u0641\u0648\u0646\u062a\u200c\u0647\u0627\u06cc \u0645\u0642\u0627\u0631\u0628\u062a\u06cc \u0628\u062e\u0634 \u0645\u06a9\u0645\u0644 \u0627\u0633\u062a \u0646\u0647 \u0642\u062f\u0645 \u0627\u0648\u0644.", "\u062f\u0631\u0645\u0627\u0646 \u0628\u0627 \u067e\u0646\u06cc\u200c\u0633\u06cc\u0644\u06cc\u0646 \u067e\u0633 \u0627\u0632 \u062a\u0623\u06cc\u06cc\u062f \u0622\u0632\u0645\u0627\u06cc\u0634\u06af\u0627\u0647\u06cc \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0627\u0631\u06cc\u062a\u0631\u0648\u0645\u0627\u06cc\u0633\u06cc\u0646 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0631\u0627\u06cc \u0633\u06cc\u0641\u0644\u06cc\u0633 \u062c\u0627\u06cc\u06af\u0627\u0647 \u0642\u0648\u06cc \u0646\u062f\u0627\u0631\u062f.", "\u062a\u0623\u06cc\u06cc\u062f \u0628\u0627 FTA-Abs \u0642\u062f\u0645 \u0627\u0635\u0648\u0644\u06cc \u0628\u0639\u062f\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 130): {
   "topic": "imperforateHymen",
   "lead": "\u0627\u062d\u062a\u0628\u0627\u0633 \u0627\u062f\u0631\u0627\u0631 + \u062f\u0631\u062f\u0647\u0627\u06cc \u0644\u06af\u0646\u06cc \u0645\u06a9\u0631\u0631 \u062f\u0631 \u0646\u0648\u062c\u0648\u0627\u0646 \u0628\u0627 \u0628\u0631\u062c\u0633\u062a\u06af\u06cc \u0628\u0646\u0641\u0634 \u0632\u06cc\u0631 \u0645\u062c\u0631\u0627\u06cc \u0627\u062f\u0631\u0627\u0631 \u062f\u0631 \u0645\u0639\u0627\u06cc\u0646\u0647: \u0647\u0627\u06cc\u0645\u0646 \u0628\u062f\u0648\u0646 \u0633\u0648\u0631\u0627\u062e (\u0647\u0645\u0627\u062a\u0648\u06a9\u0648\u0644\u067e\u0648\u0633 \u0634\u06a9\u0644\u200c\u06af\u0631\u0641\u062a\u0647).",
   "interpretation": "\u062c\u0645\u0639\u200c\u0634\u062f\u0646 \u062e\u0648\u0646 \u0642\u0627\u0639\u062f\u06af\u06cc \u067e\u0634\u062a \u063a\u0634\u0627\u06cc \u0647\u0627\u06cc\u0645\u0646\u060c \u062a\u0648\u062f\u0647\u0654 \u0628\u0646\u0641\u0634-\u0622\u0628\u06cc \u0628\u0631\u062c\u0633\u062a\u0647 \u062f\u0631 \u0648\u0631\u0648\u062f\u06cc \u0648\u0627\u0698\u0646 (\u0632\u06cc\u0631 \u0645\u062c\u0631\u0627) \u0645\u06cc\u200c\u0633\u0627\u0632\u062f \u0648 \u0628\u0647 \u0644\u062d\u0627\u0638 \u067e\u06cc\u0648\u0633\u062a\u06af\u06cc \u0645\u062b\u0627\u0646\u0647 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u062f \u0627\u062d\u062a\u0628\u0627\u0633 \u0627\u062f\u0631\u0627\u0631 \u0648 \u062f\u0631\u062f \u0644\u06af\u0646\u06cc \u062f\u0648\u0631\u0647\u200c\u0627\u06cc \u0627\u06cc\u062c\u0627\u062f \u06a9\u0646\u062f\u061b \u0633\u067e\u062a\u0648\u0645 \u0639\u0631\u0636\u06cc \u0645\u06a9\u0627\u0646\u06cc\u06a9 \u0628\u0647\u200c\u062e\u0635\u0648\u0635 \u062f\u0631 \u0641\u0648\u0631\u0634\u062a/\u0633\u067e\u062a\u0648\u0645 \u0639\u0631\u0636\u06cc \u0648\u0627\u0698\u0646 \u0627\u0633\u062a \u0648 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0628\u062f\u0648\u0646 \u0627\u06cc\u0646 \u0628\u0631\u062c\u0633\u062a\u06af\u06cc \u06a9\u0644\u0627\u0633\u06cc\u06a9 \u0645\u0634\u0627\u0647\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u062f\u06cc\u0648\u0631\u062a\u06cc\u06a9\u0648\u0644 \u0628\u0648\u0631\u062a\u0631\u0627/\u0633\u0646\u062f\u0631\u0645 \u0631\u0627\u06a9\u06cc\u062a\u0627\u0646\u0633\u06a9\u06cc \u0646\u06cc\u0632 \u0627\u06cc\u0646 \u062a\u0627\u0628\u0644\u0648\u06cc \u0628\u0646\u0641\u0634 \u0631\u0627 \u0646\u0645\u06cc\u200c\u0633\u0627\u0632\u0646\u062f.",
   "reasons": ["\u0647\u0627\u06cc\u0645\u0646 \u0628\u062f\u0648\u0646 \u0633\u0648\u0631\u0627\u062e \u0628\u0627 \u0627\u06cc\u0646 \u062a\u0631\u06a9\u06cc\u0628 \u062a\u0634\u062e\u06cc\u0635 \u062f\u0627\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0633\u067e\u062a\u0648\u0645 \u0639\u0631\u0636\u06cc \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0628\u0631\u062c\u0633\u062a\u06af\u06cc \u0628\u0646\u0641\u0634 \u0628\u0627\u0631\u0632 \u062f\u0631 \u0627\u0648\u0644 \u0648\u0627\u0698\u0646 \u0646\u0645\u06cc\u200c\u0633\u0627\u0632\u062f.", "\u062f\u06cc\u0648\u0631\u062a\u06cc\u06a9\u0648\u0644 \u0628\u0648\u0631\u062a\u0631\u0627 \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646 \u062c\u0631\u06cc\u0627\u0646 \u0645\u0639\u0645\u0648\u0644\u06cc \u0646\u06cc\u0633\u062a.", "\u0633\u0646\u062f\u0631\u0645 \u0631\u0627\u06a9\u06cc\u062a\u0627\u0646\u0633\u06a9\u06cc \u0628\u0627 \u0646\u0628\u0648\u062f \u0631\u062d\u0645 \u0645\u06cc\u200c\u0622\u06cc\u062f \u0646\u0647 \u0627\u062d\u062a\u0628\u0627\u0633 \u062e\u0648\u0646 \u062f\u0648\u0631\u0647\u200c\u0627\u06cc."],
  },
  (28, 131): {
   "topic": "infertilitySemenFirst",
   "lead": "\u062f\u0631 \u06a9\u0627\u0631\u0622\u067e \u0632\u0648\u062c \u0646\u0627\u0628\u0627\u0631\u0648\u0631\u060c \u0622\u0633\u0627\u0646\u200c\u062a\u0631\u06cc\u0646 \u0648 \u0627\u0631\u0632\u0627\u0646\u200c\u062a\u0631\u06cc\u0646 \u0648 \u063a\u06cc\u0631\u062a\u0647\u0627\u062c\u0645\u06cc\u200c\u062a\u0631\u06cc\u0646 \u062a\u0633\u062a \u0634\u0631\u0648\u0639\u060c \u0627\u0633\u067e\u0631\u0645\u0648\u06af\u0631\u0627\u0645 \u0645\u0631\u062f \u0627\u0633\u062a \u2014 \u0648 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0647\u0645\u0632\u0645\u0627\u0646/\u062f\u0631 \u0635\u062f\u0631 \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "interpretation": "\u0645\u0639\u06cc\u0627\u0631 \u0634\u0631\u0648\u0639 \u0622\u0646\u0627\u0644\u06cc\u0632 \u0627\u0633\u067e\u0631\u0645 \u0627\u06cc\u0646 \u0627\u0633\u062a \u06a9\u0647 \u0639\u0644\u062a \u0645\u0631\u062f\u0627\u0646\u0647 \u062f\u0631 \u0628\u062e\u0634 \u0642\u0627\u0628\u0644\u200c\u062a\u0648\u062c\u0647\u06cc \u0627\u0632 \u0646\u0627\u0632\u0627\u06cc\u06cc\u200c\u0647\u0627 \u0645\u0633\u0626\u0648\u0644 \u0627\u0633\u062a \u0648 \u0627\u06cc\u0646 \u062a\u0633\u062a \u0633\u0627\u062f\u0647 \u0648 \u063a\u06cc\u0631\u062a\u0647\u0627\u062c\u0645\u06cc\u060c \u0646\u0642\u0634 \u0627\u0635\u0644\u06cc \u062a\u0639\u06cc\u06cc\u0646 \u0645\u0633\u06cc\u0631 \u0628\u0639\u062f\u06cc (\u062a\u0633\u062a\u200c\u0647\u0627\u06cc \u062a\u062e\u0645\u062f\u0627\u0646\u06cc/\u0644\u0648\u0644\u0647\u200c\u0627\u06cc \u062f\u0631 \u0635\u0648\u0631\u062a \u0637\u0628\u06cc\u0639\u06cc \u0628\u0648\u062f\u0646) \u0631\u0627 \u062f\u0627\u0631\u062f\u061b \u062a\u0633\u062a \u067e\u0633 \u0627\u0632 \u0645\u0642\u0627\u0631\u0628\u062a \u0627\u0632 \u0628\u0631\u0646\u0627\u0645\u0647\u200c\u0647\u0627\u06cc \u0642\u062f\u06cc\u0645\u06cc \u0648 \u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0648 \u062a\u062d\u0631\u06cc\u06a9 \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc\u060c \u062c\u0632\u0648 \u0628\u0631\u0631\u0633\u06cc\u200c\u0647\u0627\u06cc \u0627\u0628\u062a\u062f\u0627\u06cc\u06cc \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0627\u0633\u067e\u0631\u0645\u0648\u06af\u0631\u0627\u0645 \u0627\u0648\u0644\u06cc\u0646 \u062a\u0633\u062a \u06a9\u0627\u0631\u0622\u067e \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062a\u0633\u062a \u067e\u0633 \u0627\u0632 \u0646\u0632\u062f\u06cc\u06a9\u06cc \u0628\u062e\u0634\u06cc \u0627\u0632 \u06a9\u0627\u0631\u0622\u067e \u0642\u062f\u06cc\u0645\u06cc \u0627\u0633\u062a \u0646\u0647 \u0642\u062f\u0645 \u0627\u0648\u0644.", "\u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u062f\u0631 \u067e\u0644\u0647\u0654 \u067e\u0627\u06cc\u0627\u0646\u06cc \u06a9\u0627\u0631\u0622\u067e (\u067e\u0633 \u0627\u0632 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0644\u0648\u0644\u0647) \u0642\u0631\u0627\u0631 \u062f\u0627\u0631\u062f.", "\u062a\u062d\u0631\u06cc\u06a9 \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u0628\u062f\u0648\u0646 \u0634\u0646\u0627\u062e\u062a \u0639\u0644\u062a \u0645\u0639\u0642\u0648\u0644 \u0646\u06cc\u0633\u062a."],
  },
  (28, 132): {
   "topic": "myomaMostCommonSymptom",
   "lead": "\u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0634\u06a9\u0627\u06cc\u062a \u0627\u062e\u062a\u0644\u0627\u0644\u200c\u0622\u0641\u0631\u06cc\u0646 \u062f\u0631 \u0645\u06cc\u0648\u0645 \u0631\u062d\u0645\u06cc\u060c \u0645\u0646\u0648\u0631\u0627\u0698\u06cc (\u0627\u0641\u0632\u0627\u06cc\u0634 \u062d\u062c\u0645 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0642\u0627\u0639\u062f\u06af\u06cc) \u0627\u0633\u062a\u060c \u0645\u062e\u0635\u0648\u0635\u0627\u064b \u0628\u0627 \u0645\u06cc\u0648\u0645\u200c\u0647\u0627\u06cc \u0633\u0627\u0628\u200c\u0645\u0648\u06a9\u0648\u0632\u0627\u0644/\u0627\u06cc\u0646\u062a\u0631\u0627\u0645\u0648\u0631\u0627\u0644.",
   "interpretation": "\u0628\u06cc\u0634\u200c\u062a\u0631\u06cc\u0646 \u0634\u06a9\u0627\u06cc\u062a \u0628\u06cc\u0645\u0627\u0631\u0627\u0646 \u0628\u0627 \u0645\u06cc\u0648\u0645 \u0631\u062d\u0645\u06cc\u060c \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0634\u062f\u06cc\u062f \u0642\u0627\u0639\u062f\u06af\u06cc (\u0645\u0646\u0648\u0631\u0627\u0698\u06cc) \u0627\u0633\u062a \u06a9\u0647 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u062f \u0628\u0647 \u06a9\u0645\u200c\u062e\u0648\u0646\u06cc \u0628\u06cc\u0646\u062c\u0627\u0645\u062f \u0648 \u0628\u06cc\u0634\u200c\u062a\u0631 \u0628\u0627 \u0645\u06cc\u0648\u0645\u200c\u0647\u0627\u06cc \u0633\u0627\u0628\u200c\u0645\u0648\u06a9\u0648\u0632\u0627\u0644 \u06cc\u0627 \u0627\u06cc\u0646\u062a\u0631\u0627\u0645\u0648\u0631\u0627\u0644 \u0628\u0632\u0631\u06af \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a\u061b \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0642\u0628\u0644 \u0627\u0632 \u0642\u0627\u0639\u062f\u06af\u06cc\u060c \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u0633 \u0627\u0632 \u0646\u0632\u062f\u06cc\u06a9\u06cc \u06cc\u0627 \u062f\u06cc\u0633\u0645\u0646\u0648\u0631\u0647 \u0634\u062f\u06cc\u062f \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u0633\u0628\u0628 \u0645\u0631\u0627\u062c\u0639\u0647\u0654 \u06a9\u0645\u200c\u062a\u0631 \u0634\u0627\u06cc\u0639\u200c\u0627\u0646\u062f.",
   "reasons": ["\u0645\u0646\u0648\u0631\u0627\u0698\u06cc \u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0634\u06a9\u0627\u06cc\u062a \u0645\u06cc\u0648\u0645 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0628\u06cc\u0646\u200c\u0642\u0627\u0639\u062f\u06af\u06cc/\u067e\u06cc\u0634 \u0627\u0632 \u0642\u0627\u0639\u062f\u06af\u06cc \u06a9\u0645\u200c\u062a\u0631 \u0634\u0627\u06cc\u0639 \u0627\u0633\u062a.", "\u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u0633 \u0627\u0632 \u0646\u0632\u062f\u06cc\u06a9\u06cc \u0628\u06cc\u0634\u200c\u062a\u0631 \u0645\u0631\u062a\u0628\u0637 \u0628\u0627 \u0622\u0633\u06cc\u0628 \u0633\u0631\u0648\u06cc\u06a9\u0633/\u0648\u0627\u0698\u0646 \u0627\u0633\u062a.", "\u062f\u0631\u062f \u0645\u0648\u0642\u0639 \u0642\u0627\u0639\u062f\u06af\u06cc (\u062f\u06cc\u0633\u0645\u0646\u0648\u0631\u0647) \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u062f \u0647\u0645\u0631\u0627\u0647 \u0628\u0627\u0634\u062f \u0648\u0644\u06cc \u0645\u0646\u0648\u0631\u0627\u0698\u06cc \u0645\u0642\u062f\u0645\u200c\u062a\u0631 \u0627\u0633\u062a."],
  },
  (28, 133): {
   "topic": "atrophicVaginitisSymptoms",
   "lead": "\u062f\u06cc\u0632\u0648\u0631\u06cc\u060c \u062a\u06a9\u0631\u0631 \u0627\u062f\u0631\u0627\u0631 \u0648 \u0634\u0628\u200c\u0627\u062f\u0631\u0627\u0631\u06cc \u062f\u0631 \u0632\u0646 \u06f7\u06f0 \u0633\u0627\u0644\u0647\u0654 \u06cc\u0627\u0626\u0633\u0647 \u0628\u0627 \u06a9\u0634\u062a \u0645\u0646\u0641\u06cc: \u0622\u062a\u0631\u0648\u0641\u06cc \u0698\u0646\u06cc\u062a\u0627\u0644-\u0627\u062f\u0631\u0627\u0631\u06cc ( \u062a\u0631\u0634\u062d \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0645\u0648\u0636\u0639\u06cc \u0645\u0646\u0627\u0633\u0628\u200c\u062a\u0631\u06cc\u0646 \u0627\u0642\u062f\u0627\u0645).",
   "interpretation": "\u062f\u0631 \u06cc\u0627\u0626\u0633\u0647\u060c \u062a\u062d\u0644\u06cc\u0644 \u0627\u067e\u06cc\u062a\u0644\u06cc\u0648\u0645 \u0645\u062c\u0627\u0631\u06cc \u0627\u062f\u0631\u0627\u0631\u06cc \u0648 \u0648\u0627\u0698\u0646 \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u06a9\u0645\u0628\u0648\u062f \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u062f \u0639\u0644\u0627\u06cc\u0645 \u062a\u062d\u0631\u06cc\u06a9\u06cc \u0627\u062f\u0631\u0627\u0631\u06cc (\u062f\u06cc\u0632\u0648\u0631\u06cc\u060c \u062a\u06a9\u0631\u0631\u060c \u0627\u0648\u0631\u0698\u0627\u0646\u0633\u06cc\u060c \u0634\u0628\u200c\u0627\u062f\u0631\u0627\u0631\u06cc) \u0628\u062f\u0647\u062f \u0648 \u0628\u0627 \u0645\u0646\u0641\u06cc \u0634\u062f\u0646 \u06a9\u0634\u062a\u060c \u0645\u0646\u0634\u0623 \u0627\u0644\u062a\u0647\u0627\u0628\u06cc \u062d\u0630\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0645\u0648\u0636\u0639\u06cc (\u06a9\u0631\u0645/\u062d\u0644\u0642\u0647\u0654 \u0648\u0627\u0698\u06cc\u0646\u0627\u0644) \u067e\u0627\u0633\u062e \u0627\u0646\u062a\u062e\u0627\u0628\u06cc \u0627\u0633\u062a \u0648 \u0627\u06cc\u0645\u06cc\u200c\u067e\u0631\u0627\u0645\u06cc\u0646/\u0633\u06cc\u067e\u0631\u0648\u0641\u0644\u0648\u06a9\u0633\u0627\u0633\u06cc\u0646/\u06a9\u0644\u0648\u0646\u06cc\u062f\u06cc\u0646 \u0647\u0631 \u06a9\u062f\u0627\u0645 \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646\u200c\u0647\u0627\u06cc \u0645\u062a\u0641\u0627\u0648\u062a\u06cc \u062f\u0627\u0631\u0646\u062f.",
   "reasons": ["\u0633\u06cc\u067e\u0631\u0648\u0641\u0644\u0648\u06a9\u0633\u0627\u0633\u06cc\u0646 \u0628\u062f\u0648\u0646 \u06a9\u0634\u062a \u0645\u062b\u0628\u062a/\u0639\u0644\u062a \u0639\u0641\u0648\u0646\u06cc \u0645\u0624\u06cc\u062f \u0646\u06cc\u0633\u062a.", "\u0627\u06cc\u0645\u06cc\u200c\u067e\u0631\u0627\u0645\u06cc\u0646 \u0628\u0631\u0627\u06cc \u0645\u062b\u0627\u0646\u0647\u0654 \u0628\u06cc\u200c\u0642\u0631\u0627\u0631 \u062f\u0631 \u0627\u06cc\u0646 \u0632\u0645\u06cc\u0646\u0647 \u0627\u0646\u062a\u062e\u0627\u0628 \u0627\u0648\u0644\u06cc\u0647 \u0646\u06cc\u0633\u062a.", "\u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0645\u0648\u0636\u0639\u06cc \u062f\u0631 \u0622\u062a\u0631\u0648\u0641\u06cc \u06cc\u0627\u0626\u0633\u0647 \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u06a9\u0644\u0648\u0646\u06cc\u062f\u06cc\u0646 \u062f\u0631 \u0627\u06cc\u0646 \u0634\u06a9\u0627\u06cc\u062a \u0627\u062f\u0631\u0627\u0631\u06cc \u06a9\u0627\u0631\u0628\u0631\u062f \u0645\u062a\u0639\u0627\u0631\u0641 \u0646\u062f\u0627\u0631\u062f."],
  },
  (28, 134): {
   "topic": "trichomoniasisSigns",
   "lead": "\u062a\u0631\u0634\u062d\u0627\u062a \u0632\u0631\u062f \u0628\u062f\u0628\u0648\u06cc \u0641\u0631\u0627\u0648\u0627\u0646 + \u062e\u0627\u0631\u0634/\u0633\u0648\u0632\u0634 + \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0628\u0627 \u0646\u0645\u0627\u06cc \u00ab\u062a\u0648\u062a\u200c\u0641\u0631\u0646\u06af\u06cc\u00bb: \u062a\u0631\u06cc\u06a9\u0648\u0645\u0648\u0646\u0627\u0633 \u0648\u0644\u0648\u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u0627\u0633\u062a.",
   "interpretation": "\u062a\u0631\u0634\u062d \u0632\u0631\u062f-\u0633\u0628\u0632 \u06a9\u0641\u200c\u0622\u0644\u0648\u062f \u0647\u0645\u0631\u0627\u0647 \u062e\u0627\u0631\u0634 \u0648 \u0633\u0648\u0632\u0634 \u0648 \u06cc\u0627\u0641\u062a\u0646 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u062a\u0648\u062a\u200c\u0641\u0631\u0646\u06af\u06cc (\u0627\u0632 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0646\u0642\u0637\u0647\u200c\u0627\u06cc \u0645\u062e\u0627\u0637\u06cc) \u0645\u062e\u0635\u0648\u0635 \u062a\u0631\u06cc\u06a9\u0648\u0645\u0648\u0646\u0627\u0633 \u0627\u0633\u062a\u061b \u06a9\u0627\u0646\u062f\u06cc\u062f\u0627 \u062a\u0631\u0634\u062d \u067e\u0646\u06cc\u0631\u06cc\u200c\u0645\u0627\u0646\u0646\u062f \u0628\u0627 \u0627\u0644\u062a\u0647\u0627\u0628 \u0648\u0644\u0648\u0627\u0631 \u062f\u0627\u0631\u062f \u0648 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0631\u0627 \u00ab\u062a\u0648\u062a\u200c\u0641\u0631\u0646\u06af\u06cc\u00bb \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f\u060c \u06af\u0627\u0631\u062f\u0646\u0644\u0627/BV \u062a\u0631\u0634\u062d \u0631\u0642\u06cc\u0642\u200c\u062a\u0631 \u0628\u062f\u0648\u0646 \u0627\u0644\u062a\u0647\u0627\u0628 \u0628\u0631\u062c\u0633\u062a\u0647 \u062f\u0627\u0631\u062f \u0648 \u06af\u0648\u0646\u0648\u06a9\u0648\u06a9 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u062a\u0631\u0634\u062d \u0686\u0631\u06a9\u06cc \u0633\u0631\u0648\u06cc\u06a9\u0627\u0644 \u0645\u06cc\u200c\u062f\u0647\u062f.",
   "reasons": ["\u06a9\u0627\u0646\u062f\u06cc\u062f\u0627 \u0628\u0627 \u062a\u0631\u0634\u062d \u067e\u0646\u06cc\u0631\u06cc \u0648 pH \u0637\u0628\u06cc\u0639\u06cc \u0645\u06cc\u200c\u0622\u06cc\u062f.", "\u06af\u0627\u0631\u062f\u0646\u0644\u0627 \u0628\u0627 \u062a\u0631\u0634\u062d \u0631\u0642\u06cc\u0642 \u0648 \u0633\u0644\u0648\u0644 \u0633\u0631\u0646\u062e \u0645\u06cc\u200c\u0622\u06cc\u062f \u0646\u0647 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u062a\u0648\u062a\u200c\u0641\u0631\u0646\u06af\u06cc.", "\u062a\u0631\u06cc\u06a9\u0648\u0645\u0648\u0646\u0627 \u0628\u0627 \u0627\u06cc\u0646 \u06cc\u0627\u0641\u062a\u0647\u200c\u0647\u0627 \u0645\u062d\u062a\u0645\u0644\u200c\u062a\u0631\u06cc\u0646 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u06af\u0648\u0646\u0648\u0631\u0647 \u062c\u0632\u0648 \u0639\u0644\u062a \u0633\u0631\u0648\u06cc\u0633\u06cc\u062a \u0627\u0633\u062a \u0646\u0647 \u0627\u06cc\u0646 \u062a\u0635\u0648\u06cc\u0631."],
  },
  (28, 135): {
   "topic": "previaBleedingDelivery",
   "lead": "\u062c\u0641\u062a \u0633\u0631\u0631\u0627\u0647\u06cc \u062f\u0631 \u06f3\u06f6 \u0647\u0641\u062a\u0647 \u0628\u0627 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u0641\u0639\u0627\u0644: \u062d\u062a\u06cc \u0628\u0627 \u0641\u0634\u0627\u0631 \u0646\u0631\u0645\u0627\u0644 \u0648 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062c\u0646\u06cc\u0646 \u0637\u0628\u06cc\u0639\u06cc\u060c \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u062e\u0637\u0631 \u0627\u06cc\u062c\u0627\u062f \u0645\u062c\u062f\u062f \u0647\u0645\u0648\u0631\u0627\u0698\u06cc\u060c \u0632\u0627\u06cc\u0645\u0627\u0646 \u0628\u0627 \u0633\u0632\u0627\u0631\u06cc\u0646 \u0634\u0627\u06cc\u0633\u062a\u0647 \u0627\u0633\u062a.",
   "interpretation": "\u062c\u0641\u062a \u0633\u0631\u0631\u0627\u0647\u06cc \u06a9\u0627\u0645\u0644 \u06cc\u06a9 \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u0642\u0637\u0639\u06cc \u0633\u0632\u0627\u0631\u06cc\u0646 \u0627\u0633\u062a \u0648 \u062f\u0631 \u06f3\u06f6 \u0647\u0641\u062a\u0647 \u0628\u0627 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0641\u0639\u0627\u0644\u060c \u0645\u062f\u0644 \u0645\u062f\u06cc\u0631\u06cc\u062a \u0627\u0646\u062a\u0638\u0627\u0631\u06cc \u062f\u06cc\u06af\u0631 \u067e\u0630\u06cc\u0631\u0641\u062a\u0646\u06cc \u0646\u06cc\u0633\u062a\u061b \u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645 \u062f\u0631 \u0627\u06cc\u0646 \u0631\u0627 \u062c\u0627\u06cc\u06af\u0627\u0647 \u0646\u062f\u0627\u0631\u062f\u060c \u00ab\u062a\u062d\u062a \u0646\u0638\u0631 \u0642\u0631\u0627\u0631 \u062f\u0627\u062f\u0646\u00bb \u062f\u0631 \u0628\u06cc\u0645\u0627\u0631\u0633\u062a\u0627\u0646 \u062e\u0637\u0631 \u062c\u0631\u06cc\u0627\u0646 \u0645\u062c\u062f\u062f \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0628\u062f\u0648\u0646 \u067e\u0627\u06cc\u0634 \u062f\u0627\u062e\u0644\u06cc \u062d\u0641\u0627\u0638\u062a\u06cc \u0627\u0633\u062a \u0648 \u0627\u06cc\u0646\u062f\u0627\u06a9\u0634\u0646 \u062f\u0631 \u062c\u0641\u062a \u0633\u0631\u0631\u0627\u0647\u06cc \u06a9\u0627\u0645\u0644 \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a.",
   "reasons": ["\u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645 \u062f\u0631 \u06a9\u0646\u062a\u0631\u0644 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u062c\u0641\u062a \u0633\u0631\u0631\u0627\u0647\u06cc \u062c\u0627\u06cc\u06af\u0627\u0647\u06cc \u0646\u062f\u0627\u0631\u062f.", "\u062a\u062d\u062a \u0646\u0638\u0631 \u062f\u0631 \u062c\u0641\u062a \u0633\u0631\u0631\u0627\u0647\u06cc \u0641\u0639\u0627\u0644\u200c\u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u06f3\u06f6 \u0647\u0641\u062a\u0647 \u0631\u06cc\u0633\u06a9\u06cc \u0627\u0633\u062a.", "\u0633\u0632\u0627\u0631\u06cc\u0646 \u062f\u0631 \u062c\u0641\u062a \u0633\u0631\u0631\u0627\u0647\u06cc \u06a9\u0627\u0645\u0644 \u0641\u0639\u0627\u0644 \u0635\u062d\u06cc\u062d \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0627\u06cc\u0646\u062f\u0627\u06a9\u0634\u0646 \u0632\u0627\u06cc\u0645\u0627\u0646 \u062f\u0631 \u062c\u0641\u062a \u0633\u0631\u0631\u0627\u0647\u06cc \u06a9\u0627\u0645\u0644 \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a \u0648 \u0628\u0647\u200c\u062e\u0637\u0631 \u0645\u06cc\u200c\u0627\u0641\u062a\u062f."],
  },
  (28, 136): {
   "topic": "gtnRuleOutNewPregnancy",
   "lead": "\u0635\u0639\u0648\u062f BHCG \u062f\u0648 \u0645\u0627\u0647 \u067e\u0633 \u0627\u0632 \u062a\u062e\u0644\u06cc\u0647\u0654 \u0645\u0648\u0644: \u0642\u0628\u0644 \u0627\u0632 \u0647\u0631 \u062f\u062e\u0627\u0644\u062a GTN\u060c \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u062c\u062f\u062f \u0631\u0627 \u0631\u062f \u06a9\u0646 \u0686\u0648\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0637\u0628\u06cc\u0639\u06cc \u062c\u062f\u06cc\u062f \u0646\u06cc\u0632 BHCG \u0635\u0639\u0648\u062f\u06cc \u0645\u06cc\u200c\u062f\u0647\u062f.",
   "interpretation": "\u0631\u0648\u0646\u062f BHCG \u067e\u0633 \u0627\u0632-\u062a\u062e\u0644\u06cc\u0647\u0654 \u0645\u0648\u0644 \u0628\u0627\u06cc\u062f \u0646\u0632\u0648\u0644\u06cc \u0628\u0627\u0634\u062f \u0648 \u0647\u0631 \u0635\u0639\u0648\u062f \u067e\u0644\u0627\u062a\u0648/\u0627\u0646\u0641\u062c\u0627\u0631 \u0635\u0639\u0648\u062f\u06cc \u0628\u0647\u200c\u0646\u0641\u0639 GTN \u0627\u0633\u062a\u060c \u0627\u0645\u0627 \u0639\u0627\u0645\u0644 \u0627\u0648\u0644\u06cc\u0647\u0654 \u0642\u0627\u0628\u0644 \u0645\u0642\u0627\u06cc\u0633\u0647\u060c \u062a\u0634\u06a9\u06cc\u0644 \u062d\u0627\u0645\u0644\u06af\u06cc \u062c\u062f\u06cc\u062f (\u0639\u0627\u0645\u0644 \u0627\u0635\u0644\u06cc \u0635\u0639\u0648\u062f \u0645\u062c\u062f\u062f) \u0627\u0633\u062a \u06a9\u0647 \u0628\u062f\u0648\u0646 \u0631\u062f \u0622\u0646 \u062f\u0631\u0645\u0627\u0646 \u0634\u06cc\u0645\u06cc\u0627\u06cc\u06cc \u062a\u062c\u0648\u06cc\u0632 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u0628\u0631\u0631\u0633\u06cc \u0645\u062a\u0627\u0633\u062a\u0627\u0632 \u0648 \u06a9\u0645\u0648\u062a\u0631\u0627\u067e\u06cc \u062f\u0631 \u0645\u0631\u0627\u062d\u0644 \u0628\u0639\u062f\u06cc \u0642\u0631\u0627\u0631 \u0645\u06cc\u200c\u06af\u06cc\u0631\u062f \u0648 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0644\u06af\u0646 \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u067e\u0627\u0633\u062e\u200c\u06af\u0648\u06cc \u0639\u0644\u062a \u0635\u0639\u0648\u062f BHCG \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0628\u0631\u0631\u0633\u06cc \u0645\u062a\u0627\u0633\u062a\u0627\u0632 \u0628\u0639\u062f \u0627\u0632 \u0631\u062f \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062c\u062f\u06cc\u062f \u0645\u0624\u06cc\u062f \u0627\u0633\u062a.", "\u06a9\u0645\u0648\u062a\u0631\u0627\u067e\u06cc \u0641\u0642\u0637 \u067e\u0633 \u0627\u0632 \u062a\u0623\u06cc\u06cc\u062f GTN \u0634\u0631\u0648\u0639 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0631\u062f \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u062c\u062f\u062f \u067e\u06cc\u0634 \u0627\u0632 \u062a\u0634\u062e\u06cc\u0635 GTN \u0642\u062f\u0645 \u0627\u0648\u0644 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0644\u06af\u0646 \u0639\u0644\u062a \u0635\u0639\u0648\u062f \u0631\u0627 \u062a\u0634\u062e\u06cc\u0635 \u0646\u0645\u06cc\u200c\u062f\u0647\u062f."],
  },
  (28, 137): {
   "topic": "oligohydramniosRenal",
   "lead": "\u0627\u0644\u06cc\u06af\u0648\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u067e\u0633 \u0627\u0632 \u06f2\u06f0 \u0647\u0641\u062a\u0647: \u0627\u062f\u0631\u0627\u0631 \u062c\u0646\u06cc\u0646 \u0645\u0646\u0628\u0639 \u0627\u0635\u0644\u06cc \u0622\u0628 \u0622\u0645\u0646\u06cc\u0648\u062a\u06cc\u06a9 \u0627\u0633\u062a \u0648 \u0627\u0648\u0644\u06cc\u0646 \u0631\u0627\u0633\u062a\u06cc\u200c\u0622\u0632\u0645\u0627\u06cc\u06cc\u060c \u0628\u0631\u0631\u0633\u06cc \u0633\u06cc\u0633\u062a\u0645 \u06a9\u0644\u06cc\u0647/\u0627\u062f\u0631\u0627\u0631\u06cc \u062c\u0646\u06cc\u0646\u06cc (\u0622\u0698\u0646\u0632\u06cc \u06a9\u0644\u06cc\u0647\u060c \u0627\u0646\u0633\u062f\u0627\u062f\u060c \u062f\u06cc\u0633\u200c\u067e\u0644\u0627\u0632\u06cc \u06a9\u06cc\u0633\u062a\u06cc\u06a9) \u0627\u0633\u062a.",
   "interpretation": "\u062f\u0631 \u0646\u06cc\u0645\u0647\u0654 \u062f\u0648\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc\u060c \u0645\u0627\u06cc\u0639 \u0622\u0645\u0646\u06cc\u0648\u062a\u06cc\u06a9 \u0628\u0647\u200c\u062a\u062f\u0631\u06cc\u062c \u0627\u0632 \u0627\u062f\u0631\u0627\u0631 \u062c\u0646\u06cc\u0646 \u0633\u0627\u062e\u062a\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u06a9\u0627\u0633\u062a\u0647\u200c\u0634\u062f\u0646 \u0634\u062f\u06cc\u062f \u0622\u0646 \u0628\u06cc\u0634\u200c\u062a\u0631 \u0627\u0632 \u062c\u0646\u0633 \u0622\u0633\u06cc\u0628 \u062a\u0648\u0644\u06cc\u062f/\u062f\u0641\u0639 \u0627\u062f\u0631\u0627\u0631 \u062c\u0646\u06cc\u0646\u06cc \u0627\u0633\u062a\u061b \u0646\u0627\u0647\u0646\u062c\u0627\u0631\u06cc\u200c\u0647\u0627\u06cc \u0642\u0644\u0628 \u0628\u06cc\u0634\u200c\u062a\u0631 \u0628\u0627 \u0647\u06cc\u062f\u0631\u0648\u067e\u0633 \u0647\u0645\u0631\u0627\u0647\u200c\u0627\u0646\u062f\u060c \u0627\u0646\u0633\u062f\u0627\u062f \u062f\u0633\u062a\u06af\u0627\u0647 \u06af\u0648\u0627\u0631\u0634 \u0628\u0627 \u067e\u0644\u06cc\u200c\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u0645\u06cc\u200c\u0622\u06cc\u062f \u0648 \u0627\u062e\u062a\u0644\u0627\u0644\u0627\u062a CNS \u0646\u06cc\u0632 \u062f\u0631 \u0627\u0644\u06af\u0648\u06cc \u0645\u0635\u0631\u0641 \u0645\u0627\u06cc\u0639 (\u0628\u0644\u0639 \u06a9\u0631\u062f\u0646 \u0646\u0627\u06a9\u0627\u0641\u06cc) \u0646\u0642\u0634\u06cc \u062f\u0631 \u0627\u0644\u06cc\u06af\u0648\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u0646\u062f\u0627\u0631\u0646\u062f.",
   "reasons": ["\u0628\u0631\u0631\u0633\u06cc \u0622\u0646\u0648\u0645\u0627\u0644\u06cc \u06a9\u0644\u06cc\u0648\u06cc \u062f\u0631 \u0627\u0644\u06cc\u06af\u0648\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0622\u0646\u0648\u0645\u0627\u0644\u06cc \u0642\u0644\u0628\u06cc \u0628\u06cc\u0634\u200c\u062a\u0631 \u0628\u0627 \u0647\u06cc\u062f\u0631\u0648\u067e\u0633 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a.", "\u0627\u0646\u0633\u062f\u0627\u062f \u062f\u0633\u062a\u06af\u0627\u0647 \u06af\u0648\u0627\u0631\u0634 \u0628\u0627 \u067e\u0644\u06cc\u200c\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u0645\u06cc\u200c\u0622\u06cc\u062f \u0646\u0647 \u0627\u0644\u06cc\u06af\u0648\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633.", "\u0646\u0627\u0647\u0646\u062c\u0627\u0631\u06cc CNS \u0627\u0644\u06af\u0648\u06cc \u0631\u0628\u0637 \u0645\u0633\u062a\u0642\u06cc\u0645\u06cc \u0628\u0627 \u06a9\u0645\u200c\u0634\u062f\u0646 \u0645\u0627\u06cc\u0639 \u0646\u062f\u0627\u0631\u062f."],
  },
  (28, 138): {
   "topic": "pphMostCommonCause",
   "lead": "\u0622\u062a\u0648\u0646\u06cc \u0631\u062d\u0645\u06cc \u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0639\u0644\u062a \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 (\u062d\u062f\u0648\u062f \u06f7\u06f0-\u06f8\u06f0\u066a \u0645\u0648\u0627\u0631\u062f) \u0627\u0633\u062a \u0648 \u0627\u0646\u0648\u0627\u0639 \u0634\u062f\u06cc\u062f \u0646\u06cc\u0632 \u0648\u0642\u062a\u06cc \u0628\u0631\u0622\u06cc\u0646\u062f \u0639\u0644\u0644 \u062a\u0631\u06a9\u06cc\u0628\u06cc \u0634\u0648\u062f \u0628\u0627\u0642\u06cc \u0645\u06cc\u200c\u0645\u0627\u0646\u062f.",
   "interpretation": "\u062f\u0631 \u0686\u0647\u0627\u0631 T \u0639\u0644\u0644 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 (Tone/Trauma/Tissue/Thrombin)\u060c \u0628\u06cc\u0634\u200c\u062a\u0631\u06cc\u0646 \u0633\u0647\u0645 \u0628\u0627 \u0622\u062a\u0648\u0646\u06cc \u0631\u062d\u0645 (\u0636\u0639\u0641 \u062a\u0648\u0646 \u0639\u0636\u0644\u0627\u0646\u06cc \u0628\u0627 \u0634\u0644 \u0645\u0627\u0646\u062f\u0646 \u0631\u062d\u0645) \u0627\u0633\u062a \u0648 \u067e\u0627\u0631\u06af\u06cc \u062f\u0633\u062a\u06af\u0627\u0647 \u062a\u0646\u0627\u0633\u0644\u06cc\u060c \u0628\u0642\u0627\u06cc\u0627\u06cc \u062c\u0641\u062a \u0648 \u0627\u062e\u062a\u0644\u0627\u0644\u0627\u062a \u0627\u0646\u0639\u0642\u0627\u062f\u06cc \u0639\u0644\u0644 \u0628\u0639\u062f\u06cc\u200c\u0627\u0646\u062f\u061b \u0627\u06cc\u0646 \u062a\u0631\u062a\u06cc\u0628 \u0645\u0628\u0646\u0627\u06cc \u0627\u0648\u0644\u0648\u06cc\u062a\u200c\u0628\u0646\u062f\u06cc \u0627\u0648\u0644\u06cc\u0646 \u0627\u0642\u062f\u0627\u0645 \u062f\u0631\u0645\u0627\u0646\u06cc (\u0645\u0627\u0633\u0627\u0698 \u062f\u0648 \u062f\u0633\u062a\u06cc + \u0627\u06a9\u0633\u06cc\u200c\u062a\u0648\u0633\u06cc\u0646) \u0627\u0633\u062a.",
   "reasons": ["\u0622\u062a\u0648\u0646\u06cc \u0631\u062d\u0645 \u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0639\u0644\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u067e\u0627\u0631\u06af\u06cc\u200c\u0647\u0627\u06cc \u062f\u0633\u062a\u06af\u0627\u0647 \u0698\u0646\u06cc\u062a\u0627\u0644 \u062f\u0648\u0645\u06cc\u0646 \u0639\u0644\u062a \u062f\u0631 \u0627\u06a9\u062b\u0631 \u0622\u0645\u0627\u0631\u0647\u0627\u0633\u062a.", "\u0627\u062e\u062a\u0644\u0627\u0644\u0627\u062a \u0627\u0646\u0639\u0642\u0627\u062f\u06cc \u0627\u0632 \u0639\u0644\u0644 \u06a9\u0645\u200c\u062a\u0631 \u0634\u0627\u06cc\u0639 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646\u200c\u0627\u0646\u062f.", "\u0628\u0627\u0642\u06cc\u200c\u0645\u0627\u0646\u062f\u0646 \u062c\u0641\u062a \u0639\u0644\u062a \u0645\u0647\u0645 \u0627\u0633\u062a \u0648\u0644\u06cc \u0627\u0632 \u0622\u062a\u0648\u0646\u06cc \u06a9\u0645\u200c\u062a\u0631 \u0641\u0631\u0627\u0648\u0627\u0646\u06cc \u062f\u0627\u0631\u062f."],
  },
  (28, 139): {
   "topic": "epRupturedSurgery",
   "lead": "\u0633\u0646\u06a9\u0648\u067e + \u0647\u06cc\u067e\u0648\u062a\u0627\u0646\u0633\u06cc\u0648\u0646 \u0627\u0631\u062a\u0648\u0633\u062a\u0627\u062a\u06cc\u06a9 + \u062a\u0646\u062f\u0631\u0646\u0633 \u0648 \u0631\u06cc\u0628\u0627\u0646\u062f \u0628\u0627 \u062a\u0633\u062a \u0645\u062b\u0628\u062a \u0628\u0627\u0631\u062f\u0627\u0631\u06cc: EP \u067e\u0627\u0631\u0647\u200c\u0634\u062f\u0647\u0654 \u062f\u0627\u062e\u0644 \u0634\u06a9\u0645\u06cc \u0628\u0627 \u0646\u0627\u067e\u0627\u06cc\u062f\u0627\u0631\u06cc \u0647\u0645\u0648\u062f\u06cc\u0646\u0627\u0645\u06cc\u06a9 \u2014 \u0644\u0627\u067e\u0627\u0631\u0627\u062a\u0648\u0645\u06cc \u0627\u0648\u0631\u0698\u0627\u0646\u0633.",
   "interpretation": "\u0639\u0644\u0627\u06cc\u0645 \u0634\u0648\u06a9 (\u0633\u0646\u06a9\u0648\u067e\u060c \u0627\u0641\u062a \u0641\u0634\u0627\u0631 \u0627\u0631\u062a\u0648\u0633\u062a\u0627\u062a\u06cc\u06a9) \u0628\u0647\u200c\u0647\u0645\u0631\u0627\u0647 \u0639\u0644\u0627\u06cc\u0645 \u062a\u062d\u0631\u06cc\u06a9 \u067e\u0631\u06cc\u062a\u0648\u0646\u0647\u200c\u0622\u0644 (\u0631\u06cc\u0628\u0627\u0646\u062f) \u062f\u0631 \u0632\u0646\u200c\u0628\u0627\u0631\u062f\u0627\u0631\u0650 \u0645\u062b\u0628\u062a\u060c \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u062f\u0627\u062e\u0644 \u0634\u06a9\u0645\u06cc \u0641\u0639\u0627\u0644 \u0646\u0627\u0634\u06cc \u0627\u0632 \u067e\u0627\u0631\u06af\u06cc \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062e\u0627\u0631\u062c\u200c\u0631\u062d\u0645\u06cc \u0631\u0627 \u0645\u0637\u0631\u062d \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u067e\u0627\u06cc\u062f\u0627\u0631\u0633\u0627\u0632\u06cc \u0647\u0645\u0632\u0645\u0627\u0646 \u0648 \u0639\u0645\u0644 \u0627\u0648\u0631\u0698\u0627\u0646\u0633 (\u0644\u0627\u067e\u0627\u0631\u0627\u062a\u0648\u0645\u06cc/\u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0628\u0627 \u062a\u0648\u062c\u0647 \u0628\u0647 \u0645\u0647\u0627\u0631\u062a \u0648 \u062f\u0633\u062a\u0631\u0633\u06cc) \u0644\u0627\u0632\u0645 \u0627\u0633\u062a\u061b \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0637\u062d \u0646\u0627\u067e\u0627\u06cc\u062f\u0627\u0631\u06cc \u0641\u0642\u0637 \u0632\u0645\u0627\u0646 \u0627\u0632 \u062f\u0633\u062a \u0631\u0641\u062a\u0647 \u0627\u0633\u062a\u060c \u062a\u06cc\u062a\u0631\u0627\u0698 \u0633\u0631\u06cc\u0627\u0644\u06cc \u0646\u0627\u0645\u062a\u0639\u0627\u0631\u0641 \u0627\u0633\u062a \u0648 \u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0627\u0644\u06a9\u062a\u06cc\u0648 \u0628\u0647 \u0645\u0646\u0632\u0644\u0647\u0654 \u062a\u0623\u062e\u06cc\u0631 \u0627\u0633\u062a.",
   "reasons": ["\u0644\u0627\u067e\u0627\u0631\u0627\u062a\u0648\u0645\u06cc \u0627\u0648\u0631\u0698\u0627\u0646\u0633 \u062f\u0631 EP \u067e\u0627\u0631\u0647\u200c\u0634\u062f\u0647\u0654 \u0646\u0627\u067e\u0627\u06cc\u062f\u0627\u0631 \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u062f\u0631 \u0646\u0627\u067e\u0627\u06cc\u062f\u0627\u0631\u06cc \u0647\u0645\u0648\u062f\u06cc\u0646\u0627\u0645\u06cc\u06a9 \u0632\u0645\u0627\u0646\u200c\u0628\u0631 \u0627\u0633\u062a.", "\u062a\u06cc\u062a\u0631\u0627\u0698 \u0633\u0631\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0637\u062d \u0627\u0632 \u0646\u0627\u067e\u0627\u06cc\u062f\u0627\u0631\u06cc \u062e\u0637\u0631\u0646\u0627\u06a9 \u0627\u0633\u062a.", "\u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0627\u0644\u06a9\u062a\u06cc\u0648 \u0645\u0641\u0647\u0648\u0645 \u062a\u0639\u0648\u06cc\u0642 \u0631\u0627 \u062f\u0631 \u0627\u06cc\u0646 \u0641\u0648\u0631\u06cc\u062a \u062f\u0627\u0631\u062f."],
  },
  (28, 140): {
   "topic": "endoHyperplasiaMalignancy",
   "lead": "\u0631\u06cc\u0633\u06a9 \u062a\u0628\u062f\u06cc\u0644 \u0647\u0627\u06cc\u067e\u0631\u067e\u0644\u0627\u0632\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0628\u0647 \u0633\u0631\u0637\u0627\u0646 \u062f\u0631 \u00ab\u0647\u0627\u06cc\u067e\u0631\u067e\u0644\u0627\u0632\u06cc \u06a9\u0645\u067e\u0644\u06a9\u0633 \u0647\u0645\u0631\u0627\u0647 \u0622\u062a\u06cc\u200c\u067e\u06cc\u00bb \u0628\u06cc\u0634\u200c\u062a\u0631\u06cc\u0646 \u0627\u0633\u062a.",
   "interpretation": "\u0631\u062f\u0647\u200c\u0628\u0646\u062f\u06cc \u0647\u0627\u06cc\u067e\u0631\u067e\u0644\u0627\u0632\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0628\u0631 \u0627\u0633\u0627\u0633 \u067e\u06cc\u0686\u06cc\u062f\u06af\u06cc \u0645\u0639\u0645\u0627\u0631\u06cc (\u0633\u0627\u062f\u0647/\u06a9\u0645\u067e\u0644\u06a9\u0633) \u0648 \u0622\u062a\u06cc\u200c\u067e\u06cc \u0633\u0644\u0648\u0644\u06cc \u0627\u0633\u062a \u0648 \u062a\u062d\u0648\u0644 \u0628\u062f\u062e\u06cc\u0645 \u0639\u0645\u062f\u062a\u0627\u064b \u062a\u0648\u0633\u0637 \u0622\u062a\u06cc\u200c\u067e\u06cc \u062a\u0639\u06cc\u06cc\u0646 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u062a\u0631\u06a9\u06cc\u0628 \u067e\u06cc\u0686\u06cc\u062f\u0647\u0654 \u06a9\u0645\u067e\u0644\u06a9\u0633 \u0628\u0627 \u0622\u062a\u06cc\u200c\u067e\u06cc \u0628\u0627\u0644\u0627\u062a\u0631\u06cc\u0646 \u062f\u0631\u0635\u062f \u067e\u06cc\u0634\u0631\u0641\u062a \u0628\u0647 \u0622\u062f\u0646\u0648\u06a9\u0627\u0631\u0633\u06cc\u0646\u0648\u0645 (\u062f\u0631 \u0628\u0631\u0631\u0633\u06cc\u200c\u0647\u0627 \u062a\u0627 \u062d\u062f\u0648\u062f \u06cc\u06a9\u200c\u0633\u0648\u0645 \u0645\u0648\u0627\u0631\u062f) \u0631\u0627 \u062f\u0627\u0631\u062f \u0648 \u0641\u0631\u0645\u200c\u0647\u0627\u06cc \u0628\u062f\u0648\u0646 \u0622\u062a\u06cc\u200c\u067e\u06cc \u0631\u06cc\u0633\u06a9 \u0628\u0633\u06cc\u0627\u0631 \u067e\u0627\u06cc\u06cc\u0646\u200c\u062a\u0631\u06cc \u062f\u0627\u0631\u0646\u062f.",
   "reasons": ["\u0647\u0627\u06cc\u067e\u0631\u067e\u0644\u0627\u0632\u06cc \u0633\u0627\u062f\u0647 \u0628\u062f\u0648\u0646 \u0622\u062a\u06cc\u200c\u067e\u06cc \u0631\u06cc\u0633\u06a9 \u067e\u0627\u06cc\u06cc\u0646\u06cc \u062f\u0627\u0631\u062f.", "\u0647\u0627\u06cc\u067e\u0631\u067e\u0644\u0627\u0632\u06cc \u06a9\u0645\u067e\u0644\u06a9\u0633 \u0628\u062f\u0648\u0646 \u0622\u062a\u06cc\u200c\u067e\u06cc \u0631\u06cc\u0633\u06a9 \u0645\u062a\u0648\u0633\u0637\u06cc \u062f\u0627\u0631\u062f.", "\u0622\u062a\u06cc\u200c\u067e\u06cc \u0633\u0627\u062f\u0647 \u0646\u06cc\u0632 \u0648\u0632\u0646\u06cc \u062f\u0631 \u062a\u0628\u062f\u06cc\u0644 \u062f\u0627\u0631\u062f \u0648\u0644\u06cc \u06a9\u0645\u200c\u062a\u0631 \u0627\u0632 \u0641\u0631\u0645 \u06a9\u0645\u067e\u0644\u06a9\u0633 \u0628\u0627 \u0622\u062a\u06cc\u200c\u067e\u06cc \u0627\u0633\u062a.", "\u06a9\u0645\u067e\u0644\u06a9\u0633 \u0628\u0627 \u0622\u062a\u06cc\u200c\u067e\u06cc \u0628\u06cc\u0634\u200c\u062a\u0631\u06cc\u0646 \u0631\u06cc\u0633\u06a9 \u062a\u0628\u062f\u06cc\u0644 \u0631\u0627 \u062f\u0627\u0631\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 141): {
   "topic": "dysgerminomaChild",
   "lead": "\u062a\u0648\u062f\u0647\u0654 \u06a9\u0645\u067e\u0644\u06a9\u0633 \u062a\u062e\u0645\u062f\u0627\u0646\u06cc + \u0628\u0644\u0648\u063a \u0632\u0648\u062f\u0631\u0633 \u0648 LDH \u06f2 \u0628\u0631\u0627\u0628\u0631 \u062d\u062f \u0637\u0628\u06cc\u0639\u06cc \u062f\u0631 \u062f\u062e\u062a\u0631 \u06f8 \u0633\u0627\u0644\u0647: \u062f\u06cc\u0633\u200c\u0698\u0631\u0645\u06cc\u0646\u0648\u0645\u0627 \u062f\u0631 \u0635\u062f\u0631 \u0627\u062d\u062a\u0645\u0627\u0644\u0627\u062a.",
   "interpretation": "\u062f\u0631 \u062f\u062e\u062a\u0631\u0627\u0646 \u0646\u0648\u0646\u0647\u0627\u0644\u060c \u062a\u0648\u0645\u0648\u0631\u0647\u0627\u06cc \u0633\u0644\u0648\u0644 \u062c\u0646\u06cc\u0646\u06cc \u062a\u062e\u0645\u062f\u0627\u0646 \u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0646\u0648\u0639 \u0628\u062f\u062e\u06cc\u0645\u06cc \u062a\u062e\u0645\u062f\u0627\u0646\u200c\u0627\u0646\u062f \u0648 \u062f\u06cc\u0633\u200c\u0698\u0631\u0645\u06cc\u0646\u0648\u0645\u0627 \u0628\u0627 \u0645\u0627\u0631\u06a9\u0631 LDH \u0628\u0627\u0644\u0627 \u0645\u0634\u062e\u0635 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u062f \u0628\u0627 \u0639\u0644\u0627\u06cc\u0645 \u0646\u0627\u0634\u06cc \u0627\u0632 \u0627\u0633\u062a\u0631\u0648\u0698\u0646 (\u0628\u0644\u0648\u063a \u0632\u0648\u062f\u0631\u0633 \u06a9\u0627\u0630\u0628 \u062f\u0631 \u0628\u0631\u062e\u06cc \u0632\u06cc\u0631\u06af\u0631\u0648\u0647\u200c\u0647\u0627/\u0647\u0645\u0648\u0631\u0627\u0698\u06cc) \u0645\u0631\u0627\u062c\u0639\u0647 \u06a9\u0646\u062f\u061b \u062a\u0648\u0645\u0648\u0631 \u06a9\u06cc\u0633\u0647\u0654 \u0632\u0631\u062f\u0647 \u0628\u0627 AFP \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0622\u06cc\u062f \u0648 \u06a9\u0648\u0631\u06cc\u0648\u06a9\u0627\u0631\u0633\u06cc\u0646\u0648\u0645\u0627 \u0628\u0627 BHCG \u0648 \u062a\u0631\u0627\u062a\u0648\u0645 \u0646\u0627\u0628\u0627\u0644\u063a \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0645\u0627\u0631\u06a9\u0631\u0647\u0627\u06cc \u0645\u062a\u063a\u06cc\u0631 \u062f\u0627\u0631\u062f \u0648 \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646 \u06a9\u0645\u062a\u0631 \u0627\u0644\u06af\u0648\u06cc \u0628\u0644\u0648\u063a \u0632\u0648\u062f\u0631\u0633 \u0631\u0627 \u0645\u06cc\u200c\u062f\u0647\u062f.",
   "reasons": ["\u062f\u06cc\u0633\u200c\u0698\u0631\u0645\u06cc\u0646\u0648\u0645\u0627 \u0628\u0627 \u0628\u0627\u0644\u0627 \u0628\u0648\u062f\u0646 LDH \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062a\u0648\u0645\u0648\u0631 \u06a9\u06cc\u0633\u0647\u0654 \u0632\u0631\u062f\u0647 \u0628\u0627 AFP \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0622\u06cc\u062f \u0646\u0647 LDH \u063a\u0627\u0644\u0628.", "\u06a9\u0648\u0631\u06cc\u0648\u06a9\u0627\u0631\u0633\u06cc\u0646\u0648\u0645\u0627 \u0628\u0627 \u0633\u0637\u062d \u0628\u0627\u0644\u0627\u06cc BHCG \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a \u0646\u0647 LDH \u063a\u0627\u0644\u0628.", "\u062a\u0631\u0627\u062a\u0648\u0645 \u0646\u0627\u0628\u0627\u0644\u063a \u0645\u0627\u0631\u06a9\u0631\u0647\u0627\u06cc \u0645\u062a\u063a\u06cc\u0631 \u062f\u0627\u0631\u062f \u0648 \u0628\u0644\u0648\u063a \u0632\u0648\u062f\u0631\u0633 \u06a9\u0645\u200c\u062a\u0631 \u062f\u0627\u0631\u062f."],
  },
  (28, 142): {
   "topic": "eclampsiaMgFirst",
   "lead": "\u062a\u0634\u0646\u062c \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0627 \u0641\u0634\u0627\u0631 \u06f1\u06f8\u06f0/\u06f1\u06f0\u06f0 \u062f\u0631 \u06f2\u06f2 \u0647\u0641\u062a\u0647: \u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0648 \u0628\u0647\u062a\u0631\u06cc\u0646 \u062f\u0627\u0631\u0648\u06cc \u0641\u0631\u0648\u06a9\u0627\u0647\u0646\u062f\u0647\u0654 \u062a\u0634\u0646\u062c\u060c \u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645 \u0648\u0631\u06cc\u062f\u06cc.",
   "interpretation": "\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u062a\u0639\u0631\u06cc\u0641 \u0648\u0642\u0648\u0639 \u062a\u0634\u0646\u062c \u062a\u0648\u0646\u06cc\u06a9-\u06a9\u0644\u0648\u0646\u06cc\u06a9 \u062f\u0631 \u0686\u0627\u0631\u0686\u0648\u0628 \u067e\u0631\u0647\u200c\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0627\u0633\u062a \u0648 \u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645 \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u0627\u062b\u0631\u0628\u062e\u0634\u06cc \u0628\u06cc\u0634\u200c\u062a\u0631 \u0648 \u0639\u0648\u0627\u0631\u0636 \u06a9\u0645 \u0628\u0631\u0627\u06cc \u0645\u0627\u062f\u0631/\u062c\u0646\u06cc\u0646 \u0648 \u0642\u0627\u0628\u0644\u06cc\u062a \u062c\u0644\u0648\u06af\u06cc\u0631\u06cc \u0627\u0632 \u0639\u0648\u062f\u060c \u062f\u0627\u0631\u0648\u06cc \u062e\u0637 \u0627\u0648\u0644 \u0627\u0633\u062a\u061b \u0641\u0646\u06cc\u200c\u062a\u0648\u0626\u06cc\u0646 \u0648 \u0641\u0646\u0648\u0628\u0627\u0631\u0628\u06cc\u062a\u0627\u0644 \u0627\u06af\u0631 \u062a\u0634\u0646\u062c \u0645\u0642\u0627\u0648\u0645 \u0628\u0647 Mg \u06cc\u0627 \u0645\u0646\u0639 Mg \u0628\u0627\u0634\u062f \u0627\u0646\u062a\u062e\u0627\u0628 \u062f\u0648\u0645\u200c\u0627\u0646\u062f \u0648 \u062f\u06cc\u0627\u0632\u067e\u0627\u0645 \u0631\u06a9\u062a\u0627\u0644 \u062f\u0631 \u0627\u06cc\u0646 \u0686\u0627\u0631\u0686\u0648\u0628 \u0641\u0642\u0637 \u0628\u0631\u0627\u06cc \u0645\u0647\u0627\u0631 \u0641\u0648\u0631\u06cc \u0645\u062d\u062f\u0648\u062f \u0627\u0633\u062a \u0648 \u0628\u0631\u0627\u06cc \u062c\u0644\u0648\u06af\u06cc\u0631\u06cc \u0627\u0632 \u0639\u0648\u062f \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0641\u0646\u06cc\u200c\u062a\u0648\u0626\u06cc\u0646 \u0648\u0631\u06cc\u062f\u06cc \u0627\u06af\u0631 Mg \u06a9\u0646\u062a\u0631\u0644 \u0646\u06a9\u0646\u062f \u062e\u0637 \u062f\u0648\u0645 \u0627\u0633\u062a.", "\u062f\u06cc\u0627\u0632\u067e\u0627\u0645 \u0641\u0642\u0637 \u0645\u0647\u0627\u0631 \u0641\u0648\u0631\u06cc \u0627\u0633\u062a \u0648 \u0628\u0631\u0627\u06cc \u067e\u06cc\u0634\u06af\u06cc\u0631\u06cc \u0627\u0632 \u0639\u0648\u062f \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a.", "\u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645 \u0648\u0631\u06cc\u062f\u06cc \u062e\u0637 \u0627\u0648\u0644 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0641\u0646\u0648\u0628\u0627\u0631\u0628\u06cc\u062a\u0627\u0644 \u0641\u0642\u0637 \u062f\u0631 \u062a\u0634\u0646\u062c \u0645\u0642\u0627\u0648\u0645 \u0628\u0647 \u0645\u0646\u06cc\u0632\u06cc\u0645 \u06a9\u0646\u06a9\u0627\u0634 \u0645\u06cc\u200c\u0634\u0648\u062f."],
  },
  (28, 143): {
   "topic": "msafpNotIncreased",
   "lead": "\u0627\u0641\u0632\u0627\u06cc\u0634 \u0622\u0644\u0641\u0627-\u0641\u06cc\u062a\u0648\u067e\u0631\u0648\u062a\u0626\u06cc\u0646 \u0633\u0631\u0645 \u0645\u0627\u062f\u0631 \u0628\u0631\u0627\u06cc \u0646\u0642\u0635 \u0644\u0648\u0644\u0647\u0654 \u0639\u0635\u0628\u06cc\u060c \u06af\u0627\u0633\u062a\u0631\u0648\u0634\u06cc\u0632\u06cc\u0633 \u0648 \u0645\u0631\u06af \u062c\u0646\u06cc\u0646 \u0627\u062a\u0641\u0627\u0642 \u0645\u06cc\u200c\u0627\u0641\u062a\u062f \u0648\u0644\u06cc \u062f\u06cc\u0627\u0628\u062a \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0631\u0627\u0628\u0637\u0647\u0654 \u0645\u0634\u062e\u0635 \u0627\u0641\u0632\u0627\u06cc\u0634\u06cc \u0628\u0627 \u0622\u0646 \u0646\u062f\u0627\u0631\u062f.",
   "interpretation": "\u0645\u062b\u0644\u062b \u0627\u0641\u0632\u0627\u06cc\u0634 MSAFP \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u0646\u0634\u062a\u06cc \u0645\u062e\u0627\u0637/\u067e\u0648\u0633\u062a \u062c\u0646\u06cc\u0646 (NTD\u060c \u06af\u0627\u0633\u062a\u0631\u0648\u0634\u06cc\u0632\u06cc\u0633\u060c \u0627\u0646\u0633\u0641\u0627\u0644\u0648\u0633\u0644) \u06cc\u0627 \u062a\u062f\u0627\u062e\u0644\u200c\u0647\u0627\u06cc \u0641\u06cc\u0632\u06cc\u0648\u0644\u0648\u0698\u06cc\u06a9-\u067e\u0627\u062a\u0648\u0644\u0648\u0698\u06cc\u06a9 (\u0645\u0631\u06af \u062c\u0646\u06cc\u0646\u060c \u0686\u0646\u062f\u0642\u0644\u0648\u06cc\u06cc) \u0631\u062e \u0645\u06cc\u200c\u062f\u0647\u062f\u061b \u062f\u06cc\u0627\u0628\u062a \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062a\u0646\u0647\u0627 \u062a\u063a\u06cc\u06cc\u0631 \u062f\u0631 \u0648\u0632\u0646 \u062c\u0646\u06cc\u0646 \u0648 \u067e\u0631\u0632\u0647\u0627\u06cc \u0633\u0648\u062e\u062a\u06af\u06cc \u0631\u0627 \u0628\u0647\u200c\u0637\u0648\u0631 \u063a\u06cc\u0631\u0627\u062e\u062a\u0635\u0627\u0635\u06cc \u0645\u06cc\u200c\u062f\u0647\u062f \u0648 \u062c\u0632\u0648 \u0639\u0644\u0644 \u06a9\u0644\u0627\u0633\u06cc\u06a9 \u0627\u0641\u0632\u0627\u06cc\u0634 MSAFP \u0645\u062d\u0633\u0648\u0628 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["\u0646\u0642\u0635 \u0644\u0648\u0644\u0647\u0654 \u0639\u0635\u0628\u06cc \u0639\u0644\u062a \u06a9\u0644\u0627\u0633\u06cc\u06a9 \u0627\u0641\u0632\u0627\u06cc\u0634 MSAFP \u0627\u0633\u062a.", "\u062f\u06cc\u0627\u0628\u062a \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062c\u0632\u0648 \u0639\u0644\u0644 \u0627\u0641\u0632\u0627\u06cc\u0634 MSAFP \u0646\u06cc\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d (\u0627\u0633\u062a\u062b\u0646\u0627).", "\u0645\u0631\u06af \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc \u062c\u0646\u06cc\u0646 \u0639\u0644\u062a \u06a9\u0644\u0627\u0633\u06cc\u06a9 \u0627\u0641\u0632\u0627\u06cc\u0634 MSAFP \u0627\u0633\u062a.", "\u06af\u0627\u0633\u062a\u0631\u0648\u0634\u06cc\u0632\u06cc\u0633 \u0646\u06cc\u0632 \u0639\u0644\u062a \u06a9\u0644\u0627\u0633\u06cc\u06a9 \u0627\u0641\u0632\u0627\u06cc\u0634 MSAFP \u0627\u0633\u062a."],
  },
  (28, 144): {
   "topic": "sgaDefinition",
   "lead": "SGA \u06cc\u0639\u0646\u06cc \u0648\u0632\u0646 \u062a\u062e\u0645\u06cc\u0646\u06cc \u0646\u0648\u0632\u0627\u062f/\u062c\u0646\u06cc\u0646 \u06a9\u0645\u200c\u062a\u0631 \u0627\u0632 \u067e\u0631\u0633\u0646\u062a\u0627\u06cc\u0644 \u062f\u0647\u0645 \u0628\u0631\u0627\u06cc \u0633\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc.",
   "interpretation": "\u062a\u0639\u0631\u06cc\u0641 SGA (\u06a9\u0648\u0686\u06a9 \u0628\u0631\u0627\u06cc \u0633\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc) \u0645\u0628\u062a\u0646\u06cc \u0628\u0631 \u0648\u0632\u0646 \u06a9\u0645\u062a\u0631 \u0627\u0632 \u06af\u0632\u06cc\u0646\u0647\u0654 \u062f\u0647\u0645 \u0628\u0631\u0627\u06cc \u0645\u0646\u062d\u0646\u06cc \u0631\u0634\u062f \u0645\u062a\u0646\u0627\u0633\u0628 \u0628\u0627 \u0633\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc (\u062d\u062a\u06cc \u062f\u0631 \u063a\u06cc\u0627\u0628 \u0639\u0644\u062a \u0622\u0634\u06a9\u0627\u0631) \u0627\u0633\u062a\u061b \u0622\u0633\u062a\u0627\u0646\u0647\u0654 \u062f\u06cc\u06af\u0631 \u067e\u0631\u0633\u0646\u062a\u0627\u06cc\u0644 (\u0645\u062b\u0644 \u06f2\u06f0) \u0646\u06cc\u0632 \u06af\u0627\u0647\u06cc \u062f\u0631 \u0645\u0646\u0627\u0628\u0639 \u0622\u0645\u062f\u0647 \u0627\u0645\u0627 \u0642\u0631\u0627\u0631\u062f\u0627\u062f \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0647\u0645\u0627\u0646 \u062f\u0647\u0645 \u0627\u0633\u062a \u0648 \u0633\u0646\u062c\u0647\u0654 \u062f\u0648\u0631 \u0634\u06a9\u0645 \u0645\u0639\u0645\u0648\u0644 (AC) \u062f\u0631 \u062a\u0639\u0627\u0631\u06cc\u0641 IUGR \u0645\u06a9\u0645\u0644 \u0627\u0633\u062a \u0646\u0647 \u062a\u0639\u0631\u06cc\u0641 SGA.",
   "reasons": ["\u06a9\u0645\u200c\u062a\u0631 \u0627\u0632 \u067e\u0631\u0633\u0646\u062a\u0627\u06cc\u0644 \u06f2\u06f0 \u0622\u0633\u062a\u0627\u0646\u0647\u0654 \u0645\u062a\u0639\u0627\u0631\u0641 \u0646\u06cc\u0633\u062a.", "\u06a9\u0645\u200c\u062a\u0631 \u0627\u0632 \u067e\u0631\u0633\u0646\u062a\u0627\u06cc\u0644 \u06f1\u06f0 \u062a\u0639\u0631\u06cc\u0641 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f SGA \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0628\u06cc\u0634\u200c\u062a\u0631 \u0627\u0632 \u067e\u0631\u0633\u0646\u062a\u0627\u06cc\u0644 \u06f1\u06f0 \u0628\u0631\u0627\u06cc \u062f\u0648\u0631 \u0634\u06a9\u0645 \u062a\u0639\u0631\u06cc\u0641 SGA \u0646\u06cc\u0633\u062a.", "\u0628\u06cc\u0634\u200c\u062a\u0631 \u0627\u0632 \u067e\u0631\u0633\u0646\u062a\u0627\u06cc\u0644 \u06f2\u06f0 \u0646\u06cc\u0632 \u062a\u0639\u0631\u06cc\u0641 SGA \u0646\u06cc\u0633\u062a."],
  },
  (28, 145): {
   "topic": "creasyCriteria",
   "lead": "\u062f\u0631 \u0645\u0639\u06cc\u0627\u0631 Creasy \u0628\u0631\u0627\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633\u060c \u062a\u063a\u06cc\u06cc\u0631 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u0633\u062a\u061b \u00ab\u0627\u0641\u0627\u0633\u0645\u0627\u0646 \u0628\u06cc\u0634 \u0627\u0632 \u06f8\u06f0\u066a\u00bb \u0627\u0632 \u0627\u062c\u0632\u0627\u06cc \u0627\u0645\u062a\u06cc\u0627\u0632\u062f\u0647\u0646\u062f\u0647 \u0627\u0633\u062a.",
   "interpretation": "\u062c\u062f\u0648\u0644 \u0627\u0645\u062a\u06cc\u0627\u0632\u062f\u0647\u06cc Creasy \u0628\u0631\u0627\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633\u060c \u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062a \u0631\u062d\u0645\u06cc (\u0645\u062b\u0644 \u2265\u06f4 \u0628\u0627\u0631 \u062f\u0631 \u06f2\u06f0 \u062f\u0642\u06cc\u0642\u0647 \u06cc\u0627 \u2265\u06f8 \u0628\u0627\u0631 \u062f\u0631 \u06f6\u06f0 \u062f\u0642\u06cc\u0642\u0647)\u060c \u062a\u063a\u06cc\u06cc\u0631\u0627\u062a \u0633\u0631\u0648\u06cc\u06a9\u0633 (\u062f\u06cc\u0644\u0627\u062a\u0627\u0633\u06cc\u0648\u0646 \u0628\u06cc\u0634 \u0627\u0632 ~\u06f1-\u06f2 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631 \u06cc\u0627 \u0627\u0641\u0627\u0633\u0645\u0627\u0646 \u0628\u06cc\u0634 \u0627\u0632 \u06f8\u06f0\u066a)\u060c \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u062e\u0641\u06cc\u0641 \u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u0648 \u062e\u0631\u0648\u062c \u062a\u0631\u0634\u062d \u0645\u062e\u0627\u0637\u06cc \u0631\u0627 \u0627\u0645\u062a\u06cc\u0627\u0632\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u062f\u0631 \u0633\u0646\u0627\u0631\u06cc\u0648\u06cc \u0627\u06cc\u0646 \u0628\u06cc\u0645\u0627\u0631 \u00ab\u0627\u0641\u0627\u0633\u0645\u0627\u0646>\u06f8\u06f0\u066a\u00bb \u0627\u0632 \u0645\u0639\u06cc\u0627\u0631\u0647\u0627\u06cc \u0627\u0645\u062a\u06cc\u0627\u0632\u062f\u0647\u0646\u062f\u0647\u0654 \u0622\u0646 \u0627\u0633\u062a\u061b \u062f\u0648 \u06af\u0632\u06cc\u0646\u0647\u0654 \u062f\u06cc\u0644\u0627\u062a\u0627\u0633\u06cc\u0648\u0646 \u0648 \u0627\u0646\u0642\u0628\u0627\u0636 (\u06f4\u06f6 \u0627\u0646\u0642\u0628\u0627\u0636 \u062f\u0631 \u06f4\u06f0 \u062f\u0642\u06cc\u0642\u0647) \u0645\u0637\u0627\u0628\u0642 \u062a\u0639\u0631\u06cc\u0641 \u0627\u06cc\u0646 \u0645\u0639\u06cc\u0627\u0631 \u0646\u06cc\u0633\u062a\u0646\u062f \u0648 \u062c\u0632\u0621 \u0627\u062c\u0632\u0627\u06cc \u0627\u0645\u062a\u06cc\u0627\u0632\u062f\u0647\u0646\u062f\u0647 \u0634\u0645\u0631\u062f\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u0646\u062f.",
   "reasons": ["\u062f\u06cc\u0644\u0627\u062a\u0627\u0633\u06cc\u0648\u0646 \u0628\u06cc\u0634 \u0627\u0632 \u06f1 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631 \u062f\u0631 \u0646\u0648\u0644\u06cc\u200c\u067e\u0627\u0631 \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u062c\u0632\u0621 \u0631\u0648\u0634\u0646 \u0627\u06cc\u0646 \u0641\u0631\u0645\u0648\u0644 \u0646\u06cc\u0633\u062a \u0648 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0627\u0641\u0627\u0633\u0645\u0627\u0646 \u06cc\u0627 \u062a\u0631\u06a9\u06cc\u0628 \u0647\u0631 \u062f\u0648 \u0627\u0647\u0645\u06cc\u062a \u062f\u0627\u0631\u062f.", "\u062f\u06cc\u0644\u0627\u062a\u0627\u0633\u06cc\u0648\u0646>\u06f2 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631 \u062f\u0631 \u0645\u0648\u0644\u062a\u06cc\u200c\u067e\u0627\u0631 \u06af\u0632\u06cc\u0646\u0647\u0654 \u06a9\u0644\u06cc\u062f\u06cc \u0627\u06cc\u0646 \u0641\u0631\u0645\u0648\u0644 \u0646\u06cc\u0633\u062a.", "\u0627\u0641\u0627\u0633\u0645\u0627\u0646>\u06f8\u06f0\u066a \u06cc\u06a9\u06cc \u0627\u0632 \u0627\u062c\u0632\u0627\u06cc \u0627\u0645\u062a\u06cc\u0627\u0632\u062f\u0647\u0646\u062f\u0647 \u0645\u0639\u06cc\u0627\u0631 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0634\u0645\u0627\u0631\u0634 \u0627\u0646\u0642\u0628\u0627\u0636 \u062f\u0631 \u06f4\u06f0 \u062b\u0627\u0646\u06cc\u0647 \u0646\u0627\u062f\u0631\u0633\u062a \u062a\u062f\u0648\u06cc\u0646 \u0634\u062f\u0647 \u0648 \u062c\u0632\u0621 \u0645\u0639\u06cc\u0627\u0631 \u0646\u06cc\u0633\u062a."],
  },
  (28, 146): {
   "topic": "lateDecel",
   "lead": "\u062a\u0641\u0633\u06cc\u0631 \u0627\u0641\u062a \u0636\u0631\u0628\u0627\u0646 \u06a9\u0647 \u0628\u0639\u062f \u0627\u0632 \u0634\u0631\u0648\u0639 \u0627\u0646\u0642\u0628\u0627\u0636 \u0631\u062e \u062f\u0627\u062f\u0647 \u0648 \u0628\u0639\u062f \u0627\u0632 \u067e\u0627\u06cc\u0627\u0646 \u0627\u0646\u0642\u0628\u0627\u0636 \u0628\u0647 \u062e\u0637 \u067e\u0627\u06cc\u0647 \u0628\u0631\u0645\u06cc\u200c\u06af\u0631\u062f\u062f: Late Deceleration (\u0646\u0634\u0627\u0646\u0647\u0654 \u06a9\u0645\u200c\u062e\u0648\u0646\u06cc \u062c\u0641\u062a-\u062c\u0646\u06cc\u0646).",
   "interpretation": "\u0633\u0647 \u0646\u0648\u0639 \u0627\u0641\u062a \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062c\u0646\u06cc\u0646\u06cc \u0628\u0631 \u0627\u0633\u0627\u0633 \u0631\u0627\u0628\u0637\u0647\u0654 \u0632\u0645\u0627\u0646\u06cc \u0628\u0627 \u0627\u0646\u0642\u0628\u0627\u0636 \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f: \u0632\u0648\u062f\u0631\u0633 \u0642\u0631\u06cc\u0646 \u0628\u0627 \u0642\u0644\u0647\u0654 \u0627\u0646\u0642\u0628\u0627\u0636 \u0634\u0631\u0648\u0639 \u0648 \u067e\u0627\u06cc\u0627\u0646 \u0645\u06cc\u200c\u06cc\u0627\u0628\u062f \u0648 \u0628\u06cc\u200c\u0639\u0627\u0631\u0636\u0647 \u0627\u0633\u062a\u060c \u062f\u06cc\u0631\u0631\u0633 \u067e\u0633 \u0627\u0632 \u0634\u0631\u0648\u0639 \u0627\u0646\u0642\u0628\u0627\u0636 \u0622\u063a\u0627\u0632 \u0648 \u067e\u0633 \u0627\u0632 \u067e\u0627\u06cc\u0627\u0646 \u0627\u0646\u0642\u0628\u0627\u0636 \u062a\u0645\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0647\u0634\u062f\u0627\u0631 \u06a9\u0645\u200c\u0627\u06a9\u0633\u06cc\u0698\u0646\u06cc \u0627\u0633\u062a \u0648 \u0645\u062a\u063a\u06cc\u0631 \u0627\u0644\u06af\u0648\u06cc \u063a\u06cc\u0631\u062b\u0627\u0628\u062a \u0646\u0627\u0634\u06cc \u0627\u0632 \u0641\u0634\u0627\u0631 \u0631\u0648\u06cc \u0628\u0646\u062f \u0646\u0627\u0641 \u0627\u0633\u062a\u061b \u0645\u062a\u0646 \u0627\u06cc\u0646 \u0628\u06cc\u0645\u0627\u0631 (\u06a9\u0627\u0647\u0634 \u067e\u0633 \u0627\u0632 \u0634\u0631\u0648\u0639 \u0627\u0646\u0642\u0628\u0627\u0636 \u0648 \u0628\u0631\u06af\u0634\u062a \u067e\u0633 \u0627\u0632 \u0627\u062a\u0645\u0627\u0645 \u0627\u0646\u0642\u0628\u0627\u0636) \u0628\u0627 \u062f\u06cc\u0631\u0631\u0633 \u0633\u0627\u0632\u06af\u0627\u0631 \u0627\u0633\u062a.",
   "reasons": ["\u0627\u0641\u062a \u0632\u0648\u062f\u0631\u0633 \u0642\u0631\u06cc\u0646 \u0628\u0627 \u0642\u0644\u0647\u0654 \u0627\u0646\u0642\u0628\u0627\u0636 \u0634\u0631\u0648\u0639 \u0648 \u067e\u0627\u06cc\u0627\u0646 \u0645\u06cc\u200c\u06cc\u0627\u0628\u062f \u0648 \u0628\u06cc\u200c\u062e\u0637\u0631 \u0627\u0633\u062a.", "\u0627\u0641\u062a \u062f\u06cc\u0631\u0631\u0633 \u0628\u0627 \u0627\u06cc\u0646 \u0627\u0644\u06af\u0648\u06cc \u0632\u0645\u0627\u0646\u06cc \u0645\u0634\u062e\u0635 \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0627\u0641\u062a \u0645\u062a\u063a\u06cc\u0631 \u0631\u0627\u0628\u0637\u0647\u0654 \u0632\u0645\u0627\u0646\u06cc \u062b\u0627\u0628\u062a \u0628\u0627 \u0627\u0646\u0642\u0628\u0627\u0636 \u0646\u062f\u0627\u0631\u062f.", "\u0627\u0641\u062a \u0637\u0648\u0644\u0627\u0646\u06cc\u200c\u0645\u062f\u062a \u0627\u0635\u0637\u0644\u0627\u062d \u0627\u06cc\u0646 \u0627\u0644\u06af\u0648\u06cc \u0632\u0645\u0627\u0646\u06cc \u0646\u06cc\u0633\u062a."],
  },
  (28, 147): {
   "topic": "nstReactive",
   "lead": "\u062f\u0648 \u0627\u0641\u0632\u0627\u06cc\u0634 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062c\u0646\u06cc\u0646\u06cc (\u06f1\u06f5 \u0648 \u06f2\u06f5 \u0636\u0631\u0628\u0647) \u0628\u0627 \u0637\u0648\u0644 (\u06f1\u06f5 \u0648 \u06f2\u06f0 \u062b\u0627\u0646\u06cc\u0647) \u062f\u0631 NST \u06f3\u06f6 \u0647\u0641\u062a\u0647: \u0633\u0627\u0632\u0647\u0654 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u00ab\u0648\u0627\u06a9\u0646\u0634\u06cc\u00bb \u0628\u0648\u062f\u0646 \u0648 \u0646\u0634\u0627\u0646\u0647\u0654 \u0633\u0644\u0627\u0645\u062a \u0641\u0639\u0644\u06cc \u062c\u0646\u06cc\u0646 \u0627\u0633\u062a.",
   "interpretation": "NST \u0648\u0627\u06a9\u0646\u0634\u06cc \u0632\u0645\u0627\u0646\u06cc \u0627\u0633\u062a \u06a9\u0647 \u062f\u0631 \u06f2\u06f0 \u062f\u0642\u06cc\u0642\u0647 \u062d\u062f\u0627\u0642\u0644 \u062f\u0648 \u0634\u062a\u0627\u0628 \u0628\u0627 \u0627\u0628\u0639\u0627\u062f (\u2265\u06f1\u06f5 \u0636\u0631\u0628\u0647 \u0628\u0627\u0644\u0627\u06cc \u062e\u0637 \u067e\u0627\u06cc\u0647 \u0628\u0647\u200c\u0645\u062f\u062a \u2265\u06f1\u06f5 \u062b\u0627\u0646\u06cc\u0647\u061b \u062f\u0631 \u062c\u0646\u06cc\u0646\u200c\u0647\u0627\u06cc \u2264\u06f3\u06f2 \u0647\u0641\u062a\u0647 \u0645\u062b\u0644 \u2265\u06f1\u06f0 \u0636\u0631\u0628\u0647) \u0645\u0634\u0627\u0647\u062f\u0647 \u0634\u0648\u062f\u061b \u062f\u0631 \u0633\u0646 \u06f3\u06f6 \u0647\u0641\u062a\u0647 \u0627\u06cc\u0646 \u06cc\u0627\u0641\u062a\u0647 \u0628\u0647 \u0645\u0646\u0632\u0644\u0647\u0654 \u00ab\u0648\u0627\u06a9\u0646\u0634\u06cc\u00bb \u062a\u0641\u0633\u06cc\u0631 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0647\u0634\u062f\u0627\u0631 \u062a\u06a9\u0631\u0627\u0631 \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a\u061b \u00ab\u063a\u06cc\u0631\u0648\u0627\u06a9\u0646\u0634\u06cc\u00bb \u06cc\u0639\u0646\u06cc \u0646\u0628\u0648\u062f\u0646 \u0627\u06cc\u0646 \u0634\u0627\u062e\u0635\u200c\u0647\u0627 \u0648 \u0636\u0639\u0641 \u067e\u0631\u0641\u06cc\u0648\u0698\u0646 \u062c\u0641\u062a \u0628\u0627 \u06a9\u0627\u0647\u0634/\u0627\u0641\u062a\u200c\u0647\u0627\u06cc \u06af\u0630\u0631\u0627 \u062f\u0631 \u0646\u0648\u0627\u0631 \u0636\u0631\u0628\u0627\u0646 \u062f\u06cc\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f \u0646\u0647 \u0628\u0627 \u0634\u062a\u0627\u0628.",
   "reasons": ["\u063a\u06cc\u0631\u0648\u0627\u06a9\u0646\u0634\u06cc \u0628\u0627 \u0646\u0628\u0648\u062f \u0627\u06cc\u0646 \u0645\u0639\u06cc\u0627\u0631\u0647\u0627 \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f.", "NST \u0628\u0627 \u0627\u06cc\u0646 \u0627\u0633\u062a\u0641\u0627\u062f\u0647\u200c\u0647\u0627 \u0648\u0627\u06a9\u0646\u0634\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0646\u0634\u0627\u0646\u200c\u062f\u0647\u0646\u062f\u0647\u0654 \u067e\u0631\u0641\u06cc\u0648\u0698\u0646 \u0646\u0627\u06a9\u0627\u0641\u06cc \u062c\u0641\u062a \u0646\u06cc\u0633\u062a.", "\u062a\u06a9\u0631\u0627\u0631 \u0641\u0648\u0631\u06cc NST \u062f\u0631 \u0646\u062a\u06cc\u062c\u0647\u0654 \u0648\u0627\u06a9\u0646\u0634\u06cc \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a."],
  },
  (28, 148): {
   "topic": "pphAsthmaCarboprost",
   "lead": "\u062f\u0631 \u062f\u0631\u0645\u0627\u0646 \u0622\u062a\u0648\u0646\u06cc \u0631\u062d\u0645\u06cc \u0628\u06cc\u0645\u0627\u0631 \u0622\u0633\u0645\u06cc\u060c \u067e\u0631\u0648\u0633\u062a\u0627\u06af\u0644\u0627\u0646\u062f\u06cc\u0646 F2a (\u06a9\u0627\u0631\u0628\u0648\u067e\u0631\u0648\u0633\u062a) \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u062e\u0637\u0631 \u0628\u0631\u0648\u0646\u06a9\u0648\u0627\u0633\u067e\u0627\u0633\u0645 \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a\u061b \u0627\u06a9\u0633\u06cc\u200c\u062a\u0648\u0633\u06cc\u0646 \u0648 \u0627\u0631\u06af\u0648\u0646\u0648\u06cc\u0646 (\u0628\u0627 \u0627\u062d\u062a\u06cc\u0627\u0637) \u0648 \u062a\u0631\u0627\u0646\u06a9\u0633\u0627\u0645\u06cc\u06a9 \u0627\u0633\u06cc\u062f \u062c\u0627\u06cc\u06af\u0632\u06cc\u0646\u200c\u0647\u0627\u06cc \u0642\u0627\u0628\u0644 \u0642\u0628\u0648\u0644\u200c\u0627\u0646\u062f.",
   "interpretation": "\u062f\u0631 \u062e\u0637 \u062f\u0648\u0645 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646\u060c \u0633\u0647 \u0647\u06cc\u067e\u0648\u062a\u0648\u0646\u06cc\u06a9 \u0645\u0639\u0645\u0648\u0644 (\u0627\u06a9\u0633\u06cc\u200c\u062a\u0648\u0633\u06cc\u0646\u060c \u0645\u062a\u06cc\u0644\u200c\u0627\u0631\u06af\u0648\u0645\u062a\u0631\u06cc\u0646\u060c \u06a9\u0627\u0631\u0628\u0648\u067e\u0631\u0648\u0633\u062a PGF2a) \u06a9\u0627\u0631\u0628\u0631\u062f \u062f\u0627\u0631\u0646\u062f \u0648 F2a \u0628\u0647\u200c\u0639\u0644\u062a \u0627\u062b\u0631 \u0628\u0631\u0648\u0646\u06a9\u0648\u0627\u0633\u067e\u0627\u0633\u0645 \u062f\u0631 \u0622\u0633\u0645 \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a \u0648 \u062f\u0631 \u0627\u06cc\u0646 \u0628\u06cc\u0645\u0627\u0631 \u0646\u0628\u0627\u06cc\u062f \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0634\u0648\u062f\u061b \u062a\u0631\u06a9\u06cc\u0628 \u0641\u0627\u06a9\u062a\u0648\u0631 \u0647\u0641\u062a \u0646\u0648\u062a\u0631\u06a9\u06cc\u0628 \u0628\u0631\u0627\u06cc \u0622\u062a\u0648\u0646\u06cc \u0646\u06cc\u0633\u062a \u0648 \u0627\u06a9\u0633\u06cc\u200c\u062a\u0648\u0633\u06cc\u0646 \u062f\u0631 \u0622\u0633\u0645 \u0645\u0646\u0639 \u0646\u062f\u0627\u0631\u062f.",
   "reasons": ["\u0627\u06a9\u0633\u06cc\u200c\u062a\u0648\u0633\u06cc\u0646 \u062f\u0631 \u0628\u06cc\u0645\u0627\u0631 \u0622\u0633\u0645\u06cc \u0645\u0646\u0639 \u0645\u0635\u0631\u0641 \u0646\u062f\u0627\u0631\u062f.", "\u0645\u062a\u06cc\u0644\u200c\u0627\u0631\u06af\u0648\u0645\u062a\u0631\u06cc\u0646 \u062f\u0631 \u0641\u0634\u0627\u0631\u062e\u0648\u0646 \u0628\u0627\u0644\u0627 \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a \u0646\u0647 \u062f\u0631 \u0622\u0633\u0645.", "\u06a9\u0627\u0631\u0628\u0648\u067e\u0631\u0648\u0633\u062a (PGF2a) \u062f\u0631 \u0622\u0633\u0645 \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0641\u0627\u06a9\u062a\u0648\u0631 \u0647\u0641\u062a \u0646\u0648\u062a\u0631\u06a9\u06cc\u0628 \u0628\u0631\u0627\u06cc \u0647\u0645\u0648\u0644\u06cc\u0632 \u0648 DIC \u062e\u0627\u0635 \u0627\u0633\u062a \u0646\u0647 \u0622\u062a\u0648\u0646\u06cc."],
  },
  (28, 149): {
   "topic": "gdmTwoStepOgt",
   "lead": "\u062a\u0633\u062a \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u06f5\u06f0 \u06af\u0631\u0645\u06cc \u0645\u062b\u0628\u062a (\u06f1\u06f6\u06f0 \u0645\u06cc\u0644\u06cc\u200c\u06af\u0631\u0645/\u062f\u0633\u06cc\u200c\u0644\u06cc\u062a\u0631 \u062f\u0631 \u06f2\u06f4 \u0647\u0641\u062a\u0647): \u0642\u062f\u0645 \u0628\u0639\u062f\u06cc \u062a\u0633\u062a \u062e\u0648\u0631\u0627\u06a9\u06cc \u06f1\u06f0\u06f0 \u06af\u0631\u0645\u06cc \u0633\u0647\u200c\u0633\u0627\u0639\u062a\u0647 (OGTT) \u0628\u0631\u0627\u06cc \u062a\u0634\u062e\u06cc\u0635 \u0642\u0637\u0639\u06cc GDM \u0627\u0633\u062a.",
   "interpretation": "\u0628\u0631\u0646\u0627\u0645\u0647\u0654 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u062f\u0648\u0645\u0631\u062d\u0644\u0647\u200c\u0627\u06cc \u062f\u0631 \u06f2\u06f4-\u06f2\u06f8 \u0647\u0641\u062a\u0647 \u0628\u0627 \u062a\u0633\u062a \u06f5\u06f0 \u06af\u0631\u0645\u06cc (GCT) \u0622\u0633\u062a\u0627\u0646\u0647\u0654 ~\u06f1\u06f4\u06f0 \u0645\u06cc\u0644\u06cc\u200c\u06af\u0631\u0645 \u0627\u0633\u062a \u0648 \u0646\u062a\u06cc\u062c\u0647\u0654 \u06f1\u06f6\u06f0 \u0628\u0647\u200c\u0645\u0639\u0646\u0627\u06cc \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0645\u062b\u0628\u062a \u0627\u0633\u062a \u0648 \u0628\u0627\u06cc\u062f \u0628\u0627 \u062a\u0633\u062a \u062a\u062d\u0645\u0644 \u06af\u0644\u0648\u06a9\u0632 \u0633\u0647\u200c\u0633\u0627\u0639\u062a\u0647\u0654 \u06f1\u06f0\u06f0 \u06af\u0631\u0645\u06cc (\u0628\u0627 \u0622\u0633\u062a\u0627\u0646\u0647\u200c\u0647\u0627\u06cc \u0645\u0634\u062e\u0635 \u062f\u0631 \u06f4 \u0646\u0642\u0637\u0647) \u0631\u062f \u06cc\u0627 \u062a\u0623\u06cc\u06cc\u062f \u0634\u0648\u062f\u061b \u0634\u0631\u0648\u0639 \u0627\u0646\u0633\u0648\u0644\u06cc\u0646 \u067e\u06cc\u0634 \u0627\u0632 \u062a\u0634\u062e\u06cc\u0635 \u063a\u0644\u0637 \u0627\u0633\u062a \u0648 \u0631\u0698\u06cc\u0645 \u0635\u0631\u0641 \u062f\u0631 \u0627\u06cc\u0646 \u0645\u0631\u062d\u0644\u0647 \u0628\u0647\u200c\u062c\u0627\u06cc \u062a\u062b\u0628\u06cc\u062a \u062a\u0634\u062e\u06cc\u0635 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u062a\u06a9\u0631\u0627\u0631 \u06f5\u06f0 \u06af\u0631\u0645\u06cc \u067e\u0631\u0648\u062a\u06a9\u0644 \u0645\u0639\u062a\u0628\u0631 \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0627\u0646\u0633\u0648\u0644\u06cc\u0646 \u0641\u0642\u0637 \u067e\u0633 \u0627\u0632 \u062a\u0623\u06cc\u06cc\u062f \u0648 \u062f\u0631 \u0635\u0648\u0631\u062a \u0646\u06cc\u0627\u0632 \u0627\u0633\u062a.", "\u0627\u0646\u062c\u0627\u0645 OGTT \u06f1\u06f0\u06f0 \u06af\u0631\u0645\u06cc \u0633\u0647\u200c\u0633\u0627\u0639\u062a\u0647 \u0642\u062f\u0645 \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0631\u0698\u06cc\u0645 \u062f\u06cc\u0627\u0628\u062a\u06cc \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u062a\u0634\u062e\u06cc\u0635 \u0631\u0627 \u062a\u0623\u06cc\u06cc\u062f \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f.", "\u062a\u06a9\u0631\u0627\u0631 \u062a\u0633\u062a \u06f5\u06f0 \u06af\u0631\u0645\u06cc \u067e\u0631\u0648\u062a\u06a9\u0644 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0646\u06cc\u0633\u062a."],
  },
}
